insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 1', 'English Language', 'english', 'Oral Language', 'Songs', 'B1.1.1.1', 'Demonstrate understanding of a variety of songs', 'B1.1.1.1.1', 'Listen to and sing familiar songs with appropriate expressions', 'Let learners identify some familiar songs.; Let learners sing familiar songs and clap, tap and or dance to the rhythm.; Let learners answer a variety of questions on the songs.; Discuss the moral lesson in the songs with learners.', 10),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Rhymes', 'B1.1.2.1', 'Appreciate a variety of literary pieces', 'B1.1.2.1.1', 'Listen to and recite rhymes and tongue-twisters with accompanying actions', 'Have learners recite familiar rhymes.; Introduce new rhymes by performing them.; Lead learners to echo-read the rhymes.; Let learners recite the lines in groups/pairs and as individuals, as they tap or clap to the rhythm.; Guide learners to identify rhyming words and teach the accompanying actions. Note: Recycle the rhymes in the next few days for learners to memorise them.', 20),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B1.1.3.1', 'Respond to stories', 'B1.1.3.1.1', 'Listen to stories and be able to identify characters with their roles', 'Mount appropriate story pictures.; Guide learners to tell the story logically, using the pictures at each stage.; Pause and show pictures for learners to ask questions or answer questions to predict the next stage.; Let learners retell the story in a chain, using the pictures, if necessary.; Tell learners your personal response and guide them to do same. e.g. i. Why do you like the story? ii. I like the story because… iii. Which part do you like best? iv. I like where…', 30),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B1.1.4.1', 'Respond to stories', 'B1.1.4.1.2', 'Retell short stories', 'Show pictures to guide learners to retell a story told in class.; Let learners follow the pictures to retell the story logically/sequentially.; Let learners tell other stories they know.; Let storyteller pause for others to sing any appropriate song.', 40),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role-Play', 'B1.1.5.1', 'Perform stories', 'B1.1.5.1.1', 'Dramatise stories heard', 'Begin the lesson with the narration of a familiar story.; Have learners identify the characters in the story and their roles.; Have learners role-play some specific characters in groups.; Let learners talk about theirs and others’ roles.', 50),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Conversation – Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/Cultural Values, Manners and other Themes', 'B1.1.6.1', 'Use certain culturally acceptable language for communication', 'B1.1.6.1.1', 'Use appropriate greetings for different times of the day', 'Revise daily greetings by having learners identify greeting times in the day. e.g. Morning-Good morning, Afternoon-Good afternoon, Evening-Good evening.; Discuss the correct responses to these greetings.; Let learners take turns to demonstrate greetings at different times of the day and also practise the appropriate responses.; Discuss the importance of greetings.', 60),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Conversation – Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/Cultural Values, Manners and other Themes', 'B1.1.6.1', 'Use certain culturally acceptable language for communication', 'B1.1.6.1.2', 'Describe the home, people or places', 'Welcome children and have them sit in a semi-circle. Greet them and introduce the topic for discussion. Use the Community Circle Time Strategy.; Learners are provided with an opportunity to interact freely with the teacher and peers, starting with greetings.; Have learners use appropriate responses and non-verbal language (body language and facial expression) as they greet each other.; Show pictures of homes, people and places and have learners think-pair-share their observation with the person sitting next to them and with the class.', 70),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Conversation – Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/Cultural Values, Manners and other Themes', 'B1.1.6.1', 'Use certain culturally acceptable language for communication', 'B1.1.6.1.3', 'Talk about their school and places in the school', 'Use the Community Circle Time Strategy.; Show pictures of their school and places in the school (the library, the computer lab, the headmaster’s office, the playing field etc.); Have learners think-pair-share ideas/views about the pictures in pairs and then with the large group.; Have learners talk about the activities that go on in these places and their importance to the individual.', 80),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Conversation – Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/Cultural Values, Manners and other Themes', 'B1.1.6.1', 'Use certain culturally acceptable language for communication', 'B1.1.6.1.4', 'Use a wide variety of words to describe different situations and events', 'Use a conversational poster on different situations/events.; Have learners think-pair-share, looking at the various illustrations on the poster.; Have them use expressions learnt and other new ones to describe the situations and events. Have learners, working in groups, role-play the situations and events on the poster.', 90),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Conversation – Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/Cultural Values, Manners and other Themes', 'B1.1.6.2', 'Use culturally acceptable language for communication CONT’D', 'B1.1.6.2.1', 'Engage in collaborative conversation', 'Let learners, working in groups, talk about some common places in the school (e.g. canteen, head teacher’s office, library, etc.).; Lead learners, with questions, to talk about the places and their importance.; Let learners identify the importance of the places listed above.; In pairs/small groups, let learners engage in conversations on specific topics.', 100),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Conversation – Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/Cultural Values, Manners and other Themes', 'B1.1.6.2', 'Use culturally acceptable language for communication CONT’D', 'B1.1.6.2.2', 'Talk about likes and dislikes: food, animals, toys, etc', null, 110),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B1.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B1.1.7.1.1', 'Listen to and reproduce narrative texts', 'Before Reading  Activate the previous knowledge of the learners by making them think-pair-share with their friends, the cover illustrations and pictures accompanying the story.  Have them predict the story.; During Reading  Read a story. Pause at vantage points and have learners talk about the content of the text.; After Reading  Have the learners answer simple questions based on the text.  Have them role-play the events in the story.', 120),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B1.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B1.1.7.1.2', 'Recognise and relate the sequence of events in a narrative text', 'Read a narrative text aloud to learners.; Put learners in pairs/groups to identify and talk about the parts of the story (e.g. beginning, middle and ending).', 130),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B1.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B1.1.7.1.3', 'Recognise and discuss characters in a story', 'Read a story aloud to learners.; Have them discuss, in pairs/small groups, the main and minor characters in the story.; Have groups/pairs share their views with the whole class.', 140),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B1.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B1.1.7.1.4', 'Listen to and produce descriptions of pictures and objects (', 'e.g. vehicles, animals); Show pictures of common objects and animals to learners.; Have learners think-pair-share what they see in the picture. Have them describe, in groups/pairs, the pictures to one another in turns.', 150),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B1.1.8.1', 'Demonstrate understanding in asking and answering questions', 'B1.1.8.1.1', 'Use appropriate pronunciation and intonation in asking and answering Yes/No questions', 'Demonstrate Yes/No questions and their responds.; Drill learners on the questions and responses.; Let pair of learners ask and answer questions, e.g. Pupil A: Is this a book? Pupil B: Yes, it is / No, it isn’t.', 160),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B1.1.8.1', 'Demonstrate understanding in asking and answering questions', 'B1.1.8.1.2', 'Use appropriate pronunciation and intonation in asking and answering Wh', '– questions; Revise Yes/No questions.; Let learners identify some objects in the class (e.g. board, bag, chair, etc.) and use them in asking simple questions, e.g. Should I clean the board? Is that your chair? Do you have a pencil in your bag?; Introduce Wh- questions in context. e.g. i. What is this? ii. What is your name? iii. How old are you? iv. How are you?; Pair learners to ask and answer questions. Note: Yes/No questions use rising intonation and Wh is falling intonation. However, answers for both use the falling intonation.', 170),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Giving and Responding to Commands/Instructions and Making Requests', 'B1.1.9.1', 'Demonstrate understanding in commands, instructions, directions and requests', 'B1.1.9.1.1', 'Give and respond to commands and instructions', 'Give commands and instructions to learners. e.g. Command:; Keep quiet.; Hands up.; Sit down.; Bring your books.; Start work, etc.; Pair learners to give/obey commands.; Have learners listen to simple instructions and act in response.; Let learners practise by giving commands in pairs, etc. e. g. Instructions:; Draw a circle.; Draw a triangle in the circle.; Draw a square in the triangle. Response', 180),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Giving and Responding to Commands/Instructions and Making Requests', 'B1.1.9.1', 'Demonstrate understanding in commands, instructions, directions and requests', 'B1.1.9.1.2', 'Make and respond to polite requests using the word “Please”', 'Demonstrate knowledge of requests and their responses.; Let learners respond to requests using; yes, ok, etc.; Pair with learners to take turns to make and respond to polite requests. e.g. Please give me your pencil. A: May I use your pen? B: Yes/No.; Let them change roles.', 190),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Presentation', 'B1.1.10.1', 'Plan and present information and ideas for a variety of purposes', 'B1.1.10.1.1', 'Identify audience and purpose of presentation', 'Have learners to do “show and tell” to introduce a friend to his/her parents at his/her birthday party.; Create more scenarios for learners to introduce their friends. Note: Introduce expressions like “Hello, meet my Dad”, etc.', 200),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Presentation', 'B1.1.10.1', 'Plan and present information and ideas for a variety of purposes', 'B1.1.10.1.2', 'Generate and select ideas on a given topic for presentation', 'e.g. My father, My friend, etc; Introduce the activity and as learners listen and observe, talk about the topic, e.g. “My friend”.; Briefly discuss your presentation; Let learners take turns to talk about their friends.; Encourage others to ask questions after each presentation.', 210),
('Basic 1', 'English Language', 'english', 'Oral Language', 'Presentation', 'B1.1.10.1', 'Plan and present information and ideas for a variety of purposes', 'B1.1.10.1.3', 'Speak with confidence before different audiences,', 'e.g. small group, class, etc; Have learners draw members of their nuclear family.; Through think-pair-share strategy, let learners show and talk about their family members in pairs, smaller groups and as a class.; Use probing questions to have learners talk more about their family members. e.g. i. Who is this one? ii. Why did you draw him or her first?; Encourage shy learners to speak.', 220),
('Basic 1', 'English Language', 'english', 'Reading', 'Pre-Reading Activities', 'B1.2.1.1', 'Know how a text works for reading and writing B1.2.1. 2: Manipulate the sounds of the letters of English', 'B1.2.1.1.1', 'Handle books appropriately', 'Have learners Think-Pair-Share the reasons for keeping books neat and handling them well.; Lead learners to make some rules to guide the handling of books.; Demonstrate how to handle books, e.g. holding it, turning a book, opening the pages properly, etc.; Discuss the information on the cover and title pages with learners, e. g. What can you find on the cover? - The title, - Author, - Illustrations and illustrators, etc.; Call learners in turns to demonstrate how to handle books, e.g. opening a book, holding a book, etc.; Let learners, in groups, role-play how to handle books, e.g. keeping them neat.', 230),
('Basic 1', 'English Language', 'english', 'Reading', 'Pre-Reading Activities', 'B1.2.1.2', 'Manipulate the sounds of the letters of English CONT’D', 'B1.2.1.2.1', 'Orally blend two or three sounds together to make one syllable word,', 'e.g. (a-sh = ash, b-i-n = bin); Make individual sounds and have learners blend them together to make one-syllable words, e.g. (a-sh = ash, b-i-n = bin, a-t = at, a-m = am, i-n = in, c-o-t = cot).', 240),
('Basic 1', 'English Language', 'english', 'Reading', 'Pre-Reading Activities', 'B1.2.1.2', 'Manipulate the sounds of the letters of English CONT’D', 'B1.2.1.2.2', 'Orally segment spoken syllables/words into individual sounds', 'e.g. stop = s-t-o-p; Model segmenting spoken syllables/words into individual sounds, e.g. (stop = s-t-o-p, am = a-m, pot = p-o-t).; Provide opportunities for learners to practise segmenting syllables/words into individual sounds.', 250),
('Basic 1', 'English Language', 'english', 'Reading', 'Pre-Reading Activities', 'B1.2.1.2', 'Manipulate the sounds of the letters of English CONT’D', 'B1.2.1.2.3', 'Say the new word when asked to delete, add initial sound or substitute an initial, middle or final sound (Phoneme deletion, addition, substitution)', 'Say a word and model using phoneme deletion, addition and substitution strategies to say new words from the given word, e.g. - phoneme deletion: brat= rat, etc. - phoneme substitution: cat=bat, bat = bet, bet=bell, etc. - phoneme addition: all =ball, etc.', 260),
('Basic 1', 'English Language', 'english', 'Reading', 'Phonics', 'B1.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B1.2.2.1.1', 'Identify the alphabet in order', 'Introduce the lesson with alphabet songs paying attention to the letters as they sing.; Show an alphabet chart and have learners identify the letters of the alphabet (aA- zZ).; Use alphabet cards, alphabet trees, picture cards, etc. to play alphabet games. Let learners play matching games with the cards, e.g. Sound Ball Game, Find My Partner, etc.', 270),
('Basic 1', 'English Language', 'english', 'Reading', 'Phonics', 'B1.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B1.2.2.1.2', 'Recognise and produce letter names and sounds randomly', 'Have learners play alphabet games to practice recognition of letter names at random. e.g. Lucky Dip game, Treasure Hunt.; Let learners use letter cards to order the letters of the alphabet.; Have learners find out which letter comes before the other, among a given set of letters, as a whole class, in groups, in pairs and individually.; Select letters whose sound you intend to teach, e.g. two letters at a time.; Say each sound first in context and then in isolation, e.g. ants-a; Have learners repeat it after you.; Give examples of words that contain each sound at the initial, medial and final positions, e.g. bag, table, bulb; Have learners work in pairs to provide examples of words that contain the sounds.', 280),
('Basic 1', 'English Language', 'english', 'Reading', 'Phonics', 'B1.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B1.2.2.1.3', 'Understand the relationship between spelling of words and sounds of speech', 'Blend vowel sounds with consonant sounds to produce words, e.g. am, at.; Let learners segment the sounds in the words and blend them by using blending games.; Ask learners to give examples of words.; Write the words and have learners sound the individual letters and blend them to produce words.; Have learners work in pairs/groups to further practise sound segmentation and blending to produce the words.', 290),
('Basic 1', 'English Language', 'english', 'Reading', 'Phonics', 'B1.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B1.2.2.1.4', 'Blend sounds to produce simple syllables/words and blend syllables to produce words Blending sounds', 'Clap the syllables of common words. e.g. table, pencil, pen, book, boy, girl, etc.; Let learners clap the syllables of words after teacher.; Put learners into groups/pairs.; Distribute letter cards to the groups.', 300),
('Basic 1', 'English Language', 'english', 'Reading', 'Phonics', 'B1.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B1.2.2.1.5', 'Segment syllables/words into sounds', 'Revise the sounds of letters and words learners have learnt.; Demonstrate syllable segmentation by breaking two-syllable words. Break two syllable words into syllables. e.g. pencil = pen-cil baby = ba-by mother = mo-ther; Let learners read the words and use them in sentences.', 310),
('Basic 1', 'English Language', 'english', 'Reading', 'Phonics', 'B1.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B1.2.2.1.6', 'Use alphabetic knowledge to decode known words', 'Let learners sing an alphabet song.; Put them into groups and write sentences containing some new words for learners to decode by segmentation. e.g. This is a mango. This is my sister.; Have learners read similar words from the word charts.', 320),
('Basic 1', 'English Language', 'english', 'Reading', 'Word Families, Rhyming Endings and Common Digraphs', 'B1.2.3.1', 'Identify rhyming/endings words and common digraphs', 'B1.2.3.1.1', 'Use common rhyming/ending words for decoding of words', 'Introduce learners to simple word formation using the phonic slide to change the sound at the initial, medial and final positions of words, e.g. pat, mat, fat.; Have learners build on these rhyming endings.; In groups, let learners read out their words.; Have learners form sentences with these rhyming words.', 330),
('Basic 1', 'English Language', 'english', 'Reading', 'Vocabulary', 'B1.2.6.1', 'Understand word meanings and usages', 'B1.2.6.1.1', 'Read level-appropriate sight words and use many of them in meaningful sentences', 'Introduce the appropriate sight words beginning with the commonest. Write them on the board, e.g. chair, table, child, etc.; Use the word “tree” to teach the sight words.; Have learners repeat the words aloud.; Have learners use the sight words in meaningful sentences.; Tell a story and have learners identify sight words in the story.; Have learners use the sight words in meaningful sentences, e.g. determiners - the: The boy is my friend.', 340),
('Basic 1', 'English Language', 'english', 'Reading', 'Vocabulary', 'B1.2.6.1', 'Understand word meanings and usages', 'B1.2.6.1.2', 'Ask questions to find out the meaning of new words', 'As learners listen carefully, tell a story twice.; Let learners answer questions based on the story.; Have them mention words they hear in the story.; Let learners tell the meanings of some of the words.; Have learners make their own simple sentences using the key words.', 350),
('Basic 1', 'English Language', 'english', 'Reading', 'Vocabulary', 'B1.2.6.1', 'Understand word meanings and usages', 'B1.2.6.1.3', 'Use words acquired through talk and reading in conversation', 'In groups, let learners engage in conversation using familiar and high frequency words on given topics. e. g. My Classroom', 360),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.1', 'Understand texts read', 'B1.2.7.1.1', 'Use illustrations, text clues (title, headings) and context to make inferences and predictions', 'Let learners use illustrations, text and context clues to make predictions before, during and after reading to enhance comprehension of text.', 370),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.1', 'Understand texts read', 'B1.2.7.1.2', 'Ask and answer factual and inferential and applicative questions about level-appropriate texts', 'Have learners read level appropriate texts independently, with minimal support from peers/teacher.; Encourage them to ask and answer factual and inferential questions about the texts to enhance comprehension.', 380),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.1', 'Understand texts read', 'B1.2.7.1.3', 'Retell level-appropriate texts in own words', 'Use the Simple Herring Bone strategy to guide learners to retell the story in their own words. who? what? when? when? how? why?', 390),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.2', 'Use knowledge skills and techniques of reading to understand', 'B1.2.7.2.1', 'Demonstrate understanding of the purpose and features of narrative texts', 'Use examples of short and simple texts to guide learners to understand the purpose and features of narrative texts.; Have learners identify the different purposes in different narrative texts read/heard.; Have them identify the features of given texts in pairs or in groups.', 400),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.2', 'Use knowledge skills and techniques of reading to understand', 'B1.2.7.2.2', 'Describe characters and their actions in a story', 'Put learners in groups to identify and describe characters and their actions in stories read.', 410),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.2', 'Use knowledge skills and techniques of reading to understand', 'B1.2.7.2.3', 'Connect, ideas and information in stories to own experiences and knowledge of the world', 'Tell/read out texts.; Let learners answer simple questions based on the events, characters and values, etc. in the text.; Have them relate ideas and information in the stories to personal experiences and knowledge of the world.', 420),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.2', 'Use knowledge skills and techniques of reading to understand', 'B1.2.7.2.4', 'Read level-appropriate texts with prompting and support', 'Have learners read texts with all the prompting and support that can help them in their reading.', 430),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.2', 'Use knowledge skills and techniques of reading to understand', 'B1.2.7.2.5', 'Use a variety of comprehension-strategies e. g prediction before reading a text, cover page, etc', 'Begin the comprehension lesson with before reading activities that develop and activate the background knowledge of learners. e.g. K of KWL(What learners know about the topic of information text, prediction using pictures, title, treatment of vocabulary, etc.).; Continue with while reading activities to enhance their understanding of the text. e.g. a) Herring Bone strategy who? what? when? when? how? why? b) W of KWL(What the learners want to know).; End the lesson with after reading activities that help learners to organize their ideas, remember the story, use the information acquired from the text and relate it to their daily lives, e.g. answering questions, retelling the story in their own words, learners linking story to their everyday life experiences etc.', 440),
('Basic 1', 'English Language', 'english', 'Reading', 'Comprehension', 'B1.2.7.2', 'Use knowledge skills and techniques of reading to understand', 'B1.2.7.2.6', 'Identify the structure of a story', 'e.g. beginning part, middle and the end; Narrate a suitable story.; Have learners identify the structure of the story by recalling what happened at the beginning, middle and ending.', 450),
('Basic 1', 'English Language', 'english', 'Reading', 'Fluency', 'B1.2.9.1', 'Read texts with good speed, accuracy and expression', 'B1.2.9.1.1', 'Read short and simple sentences at good pace', 'Teacher models reading at a reasonable pace.; Have learners read short and simple sentences at a reasonable pace.; Let learners read in small groups.', 460),
('Basic 1', 'English Language', 'english', 'Reading', 'Fluency', 'B1.2.9.1', 'Read texts with good speed, accuracy and expression', 'B1.2.9.1.2', 'Recognise one hundred and twenty sight words including content words', 'Have learners go over the sight words they have learnt during the period.; Let learners echo-read simple texts.; Let learners play vocabulary games for vocabulary consolidation, e.g. Lucky Dip game, Pick and Say, Word Hunt.; Have learners make simple meaningful sentences with the sight words.', 470),
('Basic 1', 'English Language', 'english', 'Writing', 'Pre-Writing', 'B1.4.1.1', 'Write patterns for muscular control and hand-eye coordination', 'B1.4.1.1.1', 'Make given patterns, trace and draw various objects', 'Demonstrate vertical, horizontal and oblique strokes/patterns. e.g. /// \\\; Let learners write these strokes/patterns in the air.; Have learners write them in their books Note: If need be, learners may first make these strokes by tracing and/or joining dots. Ensure correct sitting posture and correct grip of the writing tool.', 480),
('Basic 1', 'English Language', 'english', 'Writing', 'Pre-Writing', 'B1.4.1.1', 'Write patterns for muscular control and hand-eye coordination', 'B1.4.1.1.2', 'Model various objects of interest', 'Use papers to model an object as learners observe.; Let learners, in their groups, choose and model different objects.; Let learners tell the name of the object and what it can be used for.', 490),
('Basic 1', 'English Language', 'english', 'Writing', 'Penmanship', 'B1.4.2.1', 'Copy and write letters of the alphabet correctly', 'B1.4.2.1.1', 'Copy letters of the alphabet clearly', 'Introduce learners to the lines and spaces they will be expected to write in.; Demonstrate the letter on the board and in the air several times.; Give ample practice. Let learners practise writing in the air, on sheets of paper or in jotters.; Let learners execute the writing task.; Give feedback after assessing learners’ work.', 500),
('Basic 1', 'English Language', 'english', 'Writing', 'Writing Letters – Small and Capital', 'B1.4.3.1', 'Use general skills strategies and knowledge of letter sounds to write legibly and boldly', 'B1.4.3.1.1', 'Match lower and upper case letters', 'Show a chart of letters (small and capital). e.g. A B C D E… a b c d e…; Place letter cards (small and capital letters) on teacher’s table.; Put learners into groups and ask representatives of the groups to take turns to pick and match the letter cards to the letters on the chart. Those who are able to match them correctly win points for their groups and receive stars.; Let learners write the letters in their books.', 510),
('Basic 1', 'English Language', 'english', 'Writing', 'Writing Letters – Small and Capital', 'B1.4.3.1', 'Use general skills strategies and knowledge of letter sounds to write legibly and boldly', 'B1.4.3.1.2', 'Copy the names of objects correctly in both upper and lower case letters', 'Let learners go round and observe labelled objects in the classroom.; Let learners go with their books and change sitting positions to enable them copy the names of the objects.; Let learners sit in groups to edit their work.; Have them share their work by exchanging their books with other groups to appreciate one another’s work.', 520),
('Basic 1', 'English Language', 'english', 'Writing', 'Writing Letters – Small and Capital', 'B1.4.3.1', 'Use general skills strategies and knowledge of letter sounds to write legibly and boldly', 'B1.4.3.1.3', 'Write words using both capital and small letters', 'Write words in upper and lower cases.; Model pronunciation of target words for learners to repeat.; Let learners copy the words from the board. Encourage learners to space out letters appropriately in the words. Let group leaders help other learners (who are not able to write some letters correctly).', 530),
('Basic 1', 'English Language', 'english', 'Writing', 'Labelling Items', 'B1.4.4.1', 'Draw and label simple objects', 'B1.4.4.1.1', 'Draw simple pictures of peers or various objects and use invented spelling to write about oneself', 'Have a picture of a friend or anybody and write at least three lines about the person. Paste this in a corner of the class. Have a chart of various objects labelled (e.g. objects at home in, the environment etc.) and post them on the walls of the classroom.; Have learners go round to observe the pictures.; In groups, let learners share their observations.; Ask learners to draw and label three objects of their choice.; Have each learner choose and draw a peer and write a line or two about that person.; Assist learners with spelling where necessary.; Have learners share their work with their partners.; Similarly, let learners draw pictures of themselves and write a sentence or two about them.', 540),
('Basic 1', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B1.4.5.1', 'Write words and sentences', 'B1.4.5.1.1', 'Make a list of objects in the school', 'Guide learners with questions to talk about the various areas or places in the school e.g. head teacher’s office, canteen etc.; Put learners into groups. Let each group choose a name for their group and an area or place they want to work on.; Let each group list the objects found in the place of their choice.; Have a big chart on the wall and copy their lists on the chart. Let groups take turns to edit their work.; Let learners copy the edited words into their books.', 550),
('Basic 1', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B1.4.5.1', 'Write words and sentences', 'B1.4.5.1.2', 'Write simple familiar words', 'Let learners mention their favourite dishes or food.; Let learners select one food and talk about the ingredients used in its preparation, e.g. Jollof.; Let learners mention the ingredients as teacher writes them on the board.; Let them then work as individuals, choose their own special food or dish and write the ingredients.; Let learners do peer editing.', 560),
('Basic 1', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B1.4.5.1', 'Write words and sentences', 'B1.4.5.1.3', 'Use basic descriptive words in writing simple sentence', 'Have learners identify objects in the classroom, e. g. tables, chairs, bags, etc.; Let learners tell the sizes, shapes and colours of the objects. Explain simply to them that the words talk about objects.; Have learners work in pairs to write simple sentences, describing objects in the classroom, e. g. My classroom is big. The board is long and white. The doors and windows are big. Encourage learners to write two simple sentences each (Exceptional learners should write four simple sentences).', 570),
('Basic 1', 'English Language', 'english', 'Writing', 'Controlled Writing', 'B1.4.7.1', 'Write simple compositions', 'B1.4.7.1.1', 'Find, read and copy sentences from a given substitution tables', 'Have a simple 3-4 column substitution table on the board.; Have learners identify the words that make up the table.; With examples, guide learners to form oral sentences from the substitution table.; Have learners write their sentences.; Ask pairs to do peer editing.; Invite learners to read out their sentences to the class for feedback.', 580),
('Basic 1', 'English Language', 'english', 'Writing', 'Controlled Writing', 'B1.4.7.1', 'Write simple compositions', 'B1.4.7.1.2', 'Write a simple composition using a substitution table', 'Write a simple and short composition in a substitution table and have learners copy this out.; Using Think-Pair-Share, have learners read their compositions.', 590),
('Basic 1', 'English Language', 'english', 'Writing', 'Controlled Writing', 'B1.4.7.1', 'Write simple compositions', 'B1.4.7.1.3', 'Match parts of sentences to compose meaning texts', 'Demonstrate the activity.; Have learners rearrange jumbled parts of sentences to make meaningful texts.; Let learners read their sentences to the class for feedback.', 600),
('Basic 1', 'English Language', 'english', 'Writing', 'Descriptive Writing', 'B1.4.12.1', 'Demonstrate Knowledge of description in writing', 'B1.4.12.1.1', 'Use words and simple sentences to describe self', 'Model describing yourself in 2-3 simple sentences using simple descriptive words.; Write some descriptive words and discuss them with learners.; Through questions, have pairs of learners describe themselves to each other. e.g. What is your name? - My name is.................... How old are you? - I am ...............................; Assist learners to write out their sentences.', 610),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using Capitalisation', 'B1.5.1.1', 'Apply knowledge of capitalisation in writing', 'B1.5.1.1.1', 'Write capital letters correctly', 'Through pick and write activity, revise writing of capital letters with learners.', 620),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using Capitalisation', 'B1.5.1.1', 'Apply knowledge of capitalisation in writing', 'B1.5.1.1.2', 'Use capital letters at the beginning of titles and names of people', 'Demonstrate knowledge of capital letters and invite individuals to write names with capital letters on the board.; Assist learners to write their names. Let them begin with capital letters, e.g. Kofi, Ama, Samuel, Sule.; Lead learners to write titles of people. e.g. Mr Badu, Mrs Darko', 630),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using Capitalisation', 'B1.5.1.1', 'Apply knowledge of capitalisation in writing', 'B1.5.1.1.3', 'Use capital letters to write other proper nouns Let them write the names of towns and particular places they are familiar with, beginning with capital letters,', 'e.g. names of schools, Adukrom Primary School.', 640),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using Action Words', 'B1.5.4.1', 'Apply knowledge of action words in communication', 'B1.5.4.1.1', 'Use the present tense of verbs to describe habitual actions', 'Introduce the activity and tell learners two things you do daily.; Put learners in groups to talk about the things they do everyday: e. g. I wash my face every morning.; Write the two things you do in two simple sentences and read it out to learners.; Have each learner write two of the habitual things they do. You may assist them with spelling.; Invite each of them to present their work to the class for the class to react to the presentations.', 650),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using Action Words', 'B1.5.4.1', 'Apply knowledge of action words in communication', 'B1.5.4.1.2', 'Use the present tense of verbs to express the present state of things or situations', 'Introduce the activity and demonstrate it.; Guide learners with questions to describe the state of given things or situations, e.g. My bag is red.', 660),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using Action Words', 'B1.5.4.1', 'Apply knowledge of action words in communication', 'B1.5.4.1.3', 'Use the present tense continuous form of verbs', null, 670),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using Qualifying Words – Adjectives', 'B1.5.5.1', 'Apply knowledge of adjectives in communication', 'B1.5.5.1.1', 'Identify adjectives and use them to describe self and other people', 'Have learners read level-appropriate texts describing people.; Put learners in groups to discuss the texts read. Provide questions to help them identify the descriptive words.; Have learners write simple sentences to describe themselves, using the descriptive words identified.; Have learners write parallel sentences to describe their friends.', 680),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Using SimplePrepositions', 'B1.5.7.1', 'Apply knowledge of prepositions in communication', 'B1.5.7.1.1', 'Identify and use prepositions in oral and written language to indicate position', 'State the position of various classroom objects using simple prepositions.; Give sample sentences (on sentence cards) to learners. e.g. Mary is in the room. Aba is sitting on the chair.; Let learners identify the words in, on, etc. as words that show position.; Pair up learners and have them use the prepositions identified in simple and meaningful sentences.; Let each learner write two sentences describing the position of objects in the classroom.', 690),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Spelling', 'B1.5.10.1', 'Use phonics knowledge to spell words', 'B1.5.10.1.1', 'Identify and spell simple words correctly', 'Help learners to write two letter words correctly e. g. go, so, in, on.; Using word cards, help learners to write three letter words correctly, e. g. see, low, bow.', 700),
('Basic 1', 'English Language', 'english', 'Using Writing Convention/Grammar Usage', 'Spelling', 'B1.5.10.1', 'Use phonics knowledge to spell words', 'B1.5.10.1.2', 'Fill in blank spaces in simple words', 'Provide a passage with blank spaces and help learners to fill in the gaps or spaces with familiar two or three letter words.', 710),
('Basic 1', 'English Language', 'english', 'Extensive Reading', 'Building the Love and Culture of Reading', 'B1.6.1.1', 'Read widely for pleasure and demonstrate independent reading and learning in the literary area', 'B1.6.1.1.1', 'Read a variety of age', '– appropriate books and texts from print; Using book tease or book talk, introduce the reading/ library time.; Have a variety of age appropriate books for learners to make a choice from.; Introduce picture or wordless books, pop-up and flip-the-page texts to learners.; Encourage them to read individually and in pairs, and provide support and encouragement.', 720),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Pre-Reading Activities', 'B1.1.1.1', 'Demonstrate knowledge of a song by saying the words heard in the song after listening attentively', 'B1.1.1.1.1', 'Sing familiar songs of more than six lines and recognise place names heard in the song', 'Use a recorder to play some popular songs in the community.; Ask learners to sing some of the popular songs in the community and dance to it with the gestures they can do; Let learners sing and dance to the song.; Learners should listen to a song which has names of animals, things and places.; Let learners sing and enjoy the song.; Let learners mention names of people and animals in the song they have heard.', 10),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Pre-Reading Activities', 'B1.1.1.1', 'Demonstrate knowledge of a song by saying the words heard in the song after listening attentively', 'B1.1.1.1.2', 'Recognise and discuss the items in the home and school', 'Draw some items in the home and school on a manila card.; Show some concrete items that can be found in home and school.; Lead learners to recognise the items by mentioning the names of the items and group them under the following: “School Items” and “Home Items”.; Lead learners to apply their knowledge on colours, shapes and sizes to discuss the items. For example: School: chairs tables, arm board, pencils, chalk, books, cupboards, chalkboard, etc. Home: cups, plates, bed, mat, shoes, dress, television, radio, spoons etc.', 20),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Pre-Reading Activities', 'B1.1.1.1', 'Demonstrate knowledge of a song by saying the words heard in the song after listening attentively', 'B1.1.1.1.3', 'Demonstrate the uses of the items', 'Learners should mention names of items in the home and school.; Display some of the items in the class and call learners one by one to demonstrate how the item is used for.; Lead learners through questions and answers to tell what each of the i tems are used for.', 30),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Rhymes', 'B1.1.2.1', 'Demonstrate an understanding of words in a rhyme by listening attentively', 'B1.1.2.1.1', 'Explore rhymes of about seven or more lines and recognise names of places and people heard in the rhyme', 'Using actions and gestures, teacher explores rhymes for pupils to imitate.; Learners explore rhymes accompanied by tapping, clapping and other sound making actions.; Ask learner to explore some rhymes they know.; Teacher explores rhymes to learners and help them to mention names of things and places heard in the rhymes etc.; Write the names of things mentioned on the board and say them aloud; Discuss some of the words with the learners.', 40),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B1.1.4.1', 'Exhibit knowledge of listening and retelling simple stories', 'B1.1.4.1.1', 'Discuss the characters of the story', 'Show a clip or tell a story to learners.; Use questions to elicit names of characters in stories watched or told in class from learners.', 50),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B1.1.4.1', 'Exhibit knowledge of listening and retelling simple stories', 'B1.1.4.1.2', 'Discuss the events in the story', 'Show a movie/play to learners.; Tell or read an interesting story to learners.; Discuss the story with the learners by talking about key issues.; Encourage learners to retell the actions in the story.', 60),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B1.1.4.1', 'Exhibit knowledge of listening and retelling simple stories', 'B1.1.4.1.3', 'Role play the story', 'Let learners watch the clip again.; Read the story line to the learners and direct them to role play the story.', 70),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B1.1.5.1', 'Demonstrate knowledge of oral skills through dramatisation of a story', 'B1.1.5.1.1', 'Role play a character in a story', 'Ask a learner to tell a story.; Let learners discuss issues in the story told.; Direct learners to role play the story.', 80),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B1.1.6.1', 'Demonstrate knowledge and understanding of greetings using the appropriate address terms to greet people', 'B1.1.6.1.1', 'Recognise the various categories of people to greet', 'Revise the lesson on greetings.; Ask learners to mention the people they greet.; Discuss the categories of people in the community and how they are greeted.; Demonstrate greetings of people of various categories in class.; Assist learners to recognise the various categories of people to greet. E.g. Friends, parents, elders, etc.', 90),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B1.1.6.1', 'Demonstrate knowledge and understanding of greetings using the appropriate address terms to greet people', 'B1.1.6.1.2', 'Discuss the correct terms for the various categories of people', 'Discuss with learners, various terms for greeting.; Demonstrate greetings of various categories of people using the correct terms.; Assist learners to recognise the correct terms of greeting the various categories of people.', 100),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B1.1.7.1', 'Talk about themselves, their family and friends', 'B1.1.7.1.1', 'Describe themselves', 'Put learners into groups and let learners talk about themselves.; Call learners individually to talk about themselves to the class. E.g. Their names, age and where they live etc.', 110),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B1.1.7.1', 'Talk about themselves, their family and friends', 'B1.1.7.1.2', 'Describe their family', 'Call learners out one by one to stand in front of the class to talk about their mothers, fathers and siblings.; Write a few of the said sentences on the board for learners to copy into their books after reading them aloud. E.g. their names, where they live, and where they come from.', 120),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B1.1.7.1', 'Talk about themselves, their family and friends', 'B1.1.7.1.3', 'Describe their classmates', 'Describe a friend or colleague to learners.; Ask learners to tell you what they heard.; Call learners out one by one to stand in front of the class to talk about their classmates. E.g. their names, where they live, and where they come from.', 130),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening Comprehension', 'B1.1.8.1', 'Show an understanding of answering questions from a passage', 'B1.1.8.1.1', 'Produce what the story is about and answer simple questions on the story', 'Show a movie to learners.; Lead learners through discussion to tell them what the story is about.; Tell learners an interesting story.; Ask learners questions about the story and let them answer.; Write some of the key words in the story on the board and some of the answers also on the board.; Read them aloud for learners. E.g. What is the story about? Mention a character in a story.', 140),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B1.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly by the use of question words', 'B1.1.9.1.1', 'Recognise and use the question words “what” and “who”', 'Engage a learner in a conversation using the question words “who” and “what.”; Let learners also converse in pairs using the question tags “who” and “what.”; Ask learners questions to find out if they can recognise when to use question word. E.g. “What?” and “who?”.', 150),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B1.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly by the use of question words', 'B1.1.9.1.2', 'Recognise and use the question words “where” and “when”', 'Engage a learner in a conversation using the question word “who” and “what.”; Let learners also converse in pairs using the question words / tags “who” and “what.”; Ask learners questions to find out if they can recognise when to use question word. “What?” and “who?”.; Ask learners to say a sentence each using the question words.', 160),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B1.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly by the use of question words', 'B1.1.9.1.3', 'Recognise how to answer questions on, ‘who”, “what”, “where” and” when”', 'Arrange the class in a horse shoe formation and engage learners in a group conversation using the question tags. “who”, “what”, “where” and “when.”; Ask learners questions to find out if they can recognise when to use question tags. “what?”, “who?”, “where” and “when”.; Ask some learners to write some questions consisting of the question words on the board.; Ask another learner to read and identify the question words.', 170),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B1.1.10.1', 'Exhibit knowledge of giving and responding to commands', 'B1.1.10.1.1', 'Explain what a command is', 'Write some commands on a flashcard.; Lead learners to read the commands on the flashcard.; Direct learners to demonstrate the commands they have read.; Assist learners to recognise commands. E.g: Stand up! Sit down! etc.', 180),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B1.1.10.1', 'Exhibit knowledge of giving and responding to commands', 'B1.1.10.1.2', 'Respond to four or five commands', 'Revise the commands with learners.; Call learners in pairs and let one issue a command while the other does what the command says.; Ask learners to tell you the reaction of the other learner when the command was issued.; Let learners know why they should obey commands.', 190),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B1.1.11.1', 'Demonstrate knowledge of the days of the week and say the time by the hour', 'B1.1.11.1.1', 'Discuss the times of the day', 'Write the different times of the day on a flashcard.; Lead learners to read the different times of the day.; Assist learners to recognise and mention the different times of the day. E.g.: morning, afternoon and evening.', 200),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B1.1.11.1', 'Demonstrate knowledge of the days of the week and say the time by the hour', 'B1.1.11.1.2', 'Say the names of the days of the week', 'Write the names of the days of the week on the board.; Lead learners to read the names of the days of the week.; Assist learners to recognise and mention the names of the days of the week. E.g. Monday, Tuesday, Wednesday, etc.', 210),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B1.1.11.1', 'Demonstrate knowledge of the days of the week and say the time by the hour', 'B1.1.11.1.3', 'Say the time by the hour', 'Ask a learner to tell the time for assembly and for recreation time in the school.; Discuss time with the learners using a model clock.; Assist learners through discussion to tell time by the hour. E.g.: The time is 1 o’clock. The time is 12 o’clock, etc.', 220),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Pre-Reading Activities', 'B1.2.1.1', 'Recognise and talk about objects at home and school', 'B1.2.1.1.1', 'Say the names of items in the home and the school', 'Show some concrete items to learners and ask learners to mention the names.; Write the names of some items in the home and school on a manila card.; Lead learners to mention the items on the manila card.', 230),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Print Concept', 'B1.2.2.1', 'Demonstrate knowledge on handling print materials', 'B1.2.2.1.1', 'Turn over the pages of a book gently from right to left (handle a book appropriately)', 'Tell learners not to fold a book; that will break the spine.; Discuss with learners how to keep the print material neat. For instance, by not writing/ drawing in the book', 240),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Print Concept', 'B1.2.2.1', 'Demonstrate knowledge on handling print materials', 'B1.2.2.1.2', 'Move fingers across tables and books from left to right (do picture walk) and top to bottom (Handle a book appropriately)', 'Demonstrate how reading is done holding the book appropriately for learners to observe.; Learners demonstrate how reading is done holding the book correctly.', 250),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonological and Phonemic Awareness', 'B1.2.3.1', 'Demonstrate knowledge on hearing, recognising and differentiating sounds in spoken words', 'B1.2.3.1.1', 'Recognise the location of individual sounds in one and two-syllable words (beginning or end)', 'Write the letters of the alphabet on the board.; Teach learners the corresponding sounds.; Assist learners to recognise the individual sounds in one-syllable and two syllable words. E.g. Go, come, eat, etc. E.g. Paddle, cradle, parrot, carrot, bucket, corner etc.', 260),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonological and Phonemic Awareness', 'B1.2.3.1', 'Demonstrate knowledge on hearing, recognising and differentiating sounds in spoken words', 'B1.2.3.1.2', 'Recognise and create rhyming words', 'Write rhyming words on the board.; Say them aloud for learners to repeat.; Lead learners to create rhyming words with one and two syllable words.; Let learners write the rhyming words on the board.; Put learners in groups and do creating rhyming words game among the groups.', 270),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B1.2.4.1.1', 'Blend sounds to produce syllables', 'Write the letters of the alphabet on the board.; Say the sounds aloud to learners.; Let learners say the sounds of the letters.; Lead learners to use the sounds of the letters on the board to produce syllables. Eg: /b/ + /a/ = ba; /t/ + /o/ = to etc', 280),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B1.2.4.1.2', 'Blend syllables to produce simple words', 'Write letters on the board and create some syllables from them.; Write the syllables on the board.; Lead learners to use the syllables on the board to produce simple words.; Say the simple words aloud to learners. E.g: /ba/ + /se/ = base /cry/ + /ing/ = crying.', 290),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B1.2.4.1.3', 'Segment syllables and words into sounds and words', 'Revise sounds and syllables with learners.; Write some words on the board and lead learners to segment the words into syllables and sounds.; Ask learners to write a word and divide it into syllables and then into the sounds. E.g. Pencil = /pen/ + /sil/, Pen = /p/ + /e/ + /n/, cil = /s/ + /i/ + /l/', 300),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.2', 'Demonstrate knowledge of listening and pronouncing sounds correctly', 'B1.2.4.2.1', 'Listen and say and read words with identical sounds from list of words', 'Write words with identical sounds on a flashcard.; Mention the words for learners to listen.; Lead learners to say words with identical sounds from the list of words one by one.; Allow learners to write two words with identical sounds and read to the class.; Play an audio with identical words in them and talk about the words in the audio.; Write words with identical sounds on a flashcard/board.; Read the words for learners to listen.; Lead learners to read words with identical sounds from the list of words one by one.', 310),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.2', 'Demonstrate knowledge of listening and pronouncing sounds correctly', 'B1.2.4.2.2', 'Listen, say and recognise rhyming words in poems', 'Explore a poem.; Invite a resource person explore a poem to learners.; Learners to listen and say rhyming words in the poems.; Write the identified rhyming words on the board.; Explain some of the rhyming words.', 320),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.2', 'Demonstrate knowledge of listening and pronouncing sounds correctly', 'B1.2.4.2.3', 'Listen and say diagraphs correctly', 'Write list of words that consist of both diagraphs and non-diagraphs on the board.; Discuss the words and explain diagraphs to learners.; Write some of the diagraphs on a manila card. Example...; Read the diagraphs aloud for learners to listen.; Call learners one by one to pronounce the diagraphs correctly in words.', 330),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.2', 'Demonstrate knowledge of listening and pronouncing sounds correctly', 'B1.2.4.2.4', 'Read two-syllable words', 'Write some two-syllable words on a manila card and display the card on the board.; Lead learners to read the words.; Call learners one by one to read the two syllable words.; Use some of the words to form sentences and ask learners also to form sentences with some of the words.', 340),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B1.2.4.2', 'Demonstrate knowledge of listening and pronouncing sounds correctly', 'B1.2.4.2.5', 'Recognise and say consonants in a language', 'Write the consonants on flashcards.; Show it to learners and lead them to say the consonants in a group.; Call learners one by one to recognise and mention the consonants.; Let learners write some consonants in their books.', 350),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and Content Vocabulary)', 'B1.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B1.2.5.1.1', 'Match pictures or objects with words', 'Draw some objects on the board and write their names beside them.; Lead learners to match pictures or objects with their names.; Draw more objects on the board and provide their names.; Call learners one by one to match the pictures with the names written.', 360),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and Content Vocabulary)', 'B1.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B1.2.5.1.2', 'Read labelled objects and pictures', 'Draw some objects on the board and write their names under them.; Lead learners to read the names written under the pictures.; Draw more objects on the board and provide their names.; Call learners one by one to read what is written under the pictures.', 370),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and Content Vocabulary)', 'B1.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B1.2.5.1.3', 'Recognise and read simple words on cards', 'Write some simple words on cards and display it on the board.; Lead learners to read the words on the card.; Call learners one by one to read the words as you point them (the words).', 380),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and Content Vocabulary)', 'B1.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B1.2.5.1.4', 'Group cards bearing the same words together', 'Use flash cards with words on them.; Put learners into groups and charge them to group cards bearing the same words together. NB: Teacher supervises the groups.', 390),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B1.2.6.1', 'Exhibit knowledge of answering questions based on pictures presented', 'B1.2.6.1.1', 'Answer questions based on pictures', 'Display a large picture on the board.; Ask learners questions based on the picture displayed for learners to answer. E.g. What is the colour of the mango? What shape is the watermelon? How many human beings did you see in the picture? etc. Write some of the answers on the board.', 400),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B1.2.6.1', 'Exhibit knowledge of answering questions based on pictures presented', 'B1.2.6.1.2', 'Answer questions based on simple sentences', 'Read short sentences aloud.; Lead learners to read the short sentences.; Ask questions based on the sentences read for learners to answer.', 410),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B1.2.6.1', 'Exhibit knowledge of answering questions based on pictures presented', 'B1.2.6.1.3', 'Answer questions based on text read by teacher', 'Read a short text aloud.; Encourage learners to ask questions based on the text read for their friends to answer.; Ask learners questions based on the text you have read for learners to answer.', 420),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B1.2.7.1', 'Demonstrate knowledge on reading for comprehension', 'B1.2.7.1.1', 'Do picture reading', 'Put learners into groups and provide them with a picture book.; Encourage learners to discuss the pictures among themselves while you go around to monitor.; Call leaders of the various groups to read their pictures to the whole class.', 430),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B1.2.7.1', 'Demonstrate knowledge on reading for comprehension', 'B1.2.7.1.2', 'Read simple sentences of about four to five words', 'Write simple sentences made up of four or five words on a card and display it on the board for learners to see.; Lead learners to read the sentences as a group.; Call learners to read and point to the sentences one by one.', 440),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B1.2.8.1', 'Exhibit knowledge by reading with minimal mistakes', 'B1.2.8.1.1', 'Blend syllables to form words', 'Revise syllables with learners.; Write some syllables on the board and lead learners to read them.; Lead learners through discussion to blend the syllables to form words. E.g.: /ba/ + /se/ = base /cry/ + /ing/ = crying', 450),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B1.2.8.1', 'Exhibit knowledge by reading with minimal mistakes', 'B1.2.8.1.2', 'Read aloud words and simple sentences using correct pronunciation', 'Read aloud a text or simple sentences with correct pronunciation.; Let learners say the simple sentences after you.; Call learners to read the sentences with correct pronunciation of the words in the text and simple sentences.', 460),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B1.3.1.1', 'Make given patterns, trace and draw various objects; model various objects that interest them', 'B1.3.1.1.1', 'Control wrist in letter writing and pattern drawing', 'Using a sand tray, demonstrate to learners the correct way of moving the wrist when writing letters and drawing patterns.; Call learners one by one to write the letters and draw patterns in the sand tray while you control them.; Make sure they move their wrist correctly.', 470),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B1.3.1.1', 'Make given patterns, trace and draw various objects; model various objects that interest them', 'B1.3.1.1.2', 'Trace given shapes', 'Draw broken lines on papers.; Give the papers to learners and lead them to trace the broken lines to form shapes.; Let each learner show his/her work to the class and discuss it.', 480),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B1.3.1.1', 'Make given patterns, trace and draw various objects; model various objects that interest them', 'B1.3.1.1.3', 'Write patterns of letters in continuous form', 'Write the letters of the alphabet on a manila card and show it to learners.; Lead learners to practice how to write letter patterns in continuous form.', 490),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B1.3.1.1', 'Make given patterns, trace and draw various objects; model various objects that interest them', 'B1.3.1.1.4', 'Model various objects that interest them', 'Provide learners with different objects.; Let learners recognise the objects and talk about them.; Talk about their uses and where the objects can be found.; Lead learners to model various objects that interest them individually.', 500),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Letters-Small and Capital', 'B1.3.2.1', 'Show an understanding of combining strokes to form shapes of some letters of the alphabet, write lower and upper- case letters; copy from writing cards and writing board. Trace drawings from cards', 'B1.3.2.1.1', 'Combine strokes to form shapes', 'Draw strokes of lines on papers.; Give the papers to learners and lead them to trace the strokes of lines to form shapes.; Let each learner show his/her work to the class and discuss it.', 510),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Letters-Small and Capital', 'B1.3.2.1', 'Show an understanding of combining strokes to form shapes of some letters of the alphabet, write lower and upper- case letters; copy from writing cards and writing board. Trace drawings from cards', 'B1.3.2.1.2', 'Write lower and upper-case letters', 'Write the lower and upper case letters on the board.; Talk about the letters written on the board.; Say the sounds of the letters aloud to the learners.; Lead learners to write the lower- and upper-case letters correctly.', 520),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Letters-Small and Capital', 'B1.3.2.1', 'Show an understanding of combining strokes to form shapes of some letters of the alphabet, write lower and upper- case letters; copy from writing cards and writing board. Trace drawings from cards', 'B1.3.2.1.3', 'Copy and trace letters and words from given letter cards on the board', 'Provide learners with letter cards.; Lead learners to trace the letters on the cards.; Charge learners to write the letters without tracing. NB: Teacher to go around to monitor this activity.', 530),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Letters-Small and Capital', 'B1.3.2.1', 'Show an understanding of combining strokes to form shapes of some letters of the alphabet, write lower and upper- case letters; copy from writing cards and writing board. Trace drawings from cards', 'B1.3.2.1.4', 'Trace from a given templates', 'Provide learners with templates with objects drawn on them.; Put learners into groups and lead them to trace the objects on the templates.', 540),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B1.3.3.1', 'Show an understanding of combining strokes to form shapes of letters of the alphabet and copying simple words name of people and places', 'B1.3.3.1.1', 'Combine strokes to form shapes of the letters of the alphabets correctly', 'Draw strokes on papers and give them to learners.; Ask learners to combine the strokes on the papers.; Let learners show their work to the class and discuss it with them.; Draw the strokes on the board and call learners to combine them to form letters of the alphabet.', 550),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B1.3.3.1', 'Show an understanding of combining strokes to form shapes of letters of the alphabet and copying simple words name of people and places', 'B1.3.3.1.2', 'Combine strokes to form shapes of the lower-case letters', 'Draw strokes on papers and give them to learners.; Ask learners to combine the strokes on the papers.; Let learners show their work to the class and discuss it with them.; Draw the strokes on the board and call learners to combine them to form shapes of the lower-case letters.', 560),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B1.3.3.1', 'Show an understanding of combining strokes to form shapes of letters of the alphabet and copying simple words name of people and places', 'B1.3.3.1.3', 'Combine strokes to form shapes of the upper-case letters', 'Draw strokes on papers and give them to learners. Ask learners to combine the strokes on the papers.; Let learners show their work to the class and discuss it with them.; Draw the strokes on the board and call learners to combine them to form shapes of the upper-case letters.', 570),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B1.3.3.1', 'Show an understanding of combining strokes to form shapes of letters of the alphabet and copying simple words name of people and places', 'B1.3.3.1.4', 'Copy and trace letters and words from a given letter cards on the board', 'Provide learners with letter cards.; Lead learners to trace the letters on the cards.; Guide learners to write the letters without tracing. NB: Teacher to go round to monitor this activity.', 580),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B1.3.3.2', 'Show an understanding of items in the environment/ classroom', 'B1.3.3.2.1', 'Label and mention items in the classroom/environment', 'Draw some of the items in the classroom and the environment on the board.; Ask learners to label the items and tell their uses.; Guide learners to mention the items one by one.', 590),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Copying/Writing Simple Sentences with Correct Spacing', 'B1.3.4.1', 'Exhibit knowledge of copying simple sentences with correct word spacing', 'B1.3.4.1.1', 'Copy short meaningful sentences with correct spacing', 'Ask a learner to give a simple sentence and write it on the board.; Say the sentence aloud.; Explore and write a short meaningful sentence on the board with the correct spacing.; Let learners copy the short meaningful sentences with correct spacing.', 600),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B1.5.1.1', 'Exhibit knowledge of writing capital letters', 'B1.5.1.1.1', 'Learn to write capital letters correctly', 'Write the letters of the alphabet in upper case on cards and show it to learners.; Guide learners through modelling to say them.; Ask learners to write the capital letters correctly.', 610),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B1.5.1.1', 'Exhibit knowledge of writing capital letters', 'B1.5.1.1.2', 'Use capital letters to write names', 'Write names of some objects using capital letters on flashcards.; Lead learners to read the words.; Let learners use capital letters to write names of the objects correctly.', 620),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B1.5.1.1', 'Exhibit knowledge of writing capital letters', 'B1.5.1.1.3', 'Use capital letters to write proper nouns', 'Ask learners to mention their names; write them on the board and discuss with them.; Ask them to say what they see about the letters in the names.; Write names of persons and places on manila card in capital letters.; Guide learners to read the names and discuss the names with them.; Let learners use capital letters to write the proper nouns.', 630),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B1.5.3.1', 'Show an understanding of writing action words', 'B1.5.3.1.1', 'Write two letter action words', 'Ask learners to mention some action words on the board.; List the words on the board and say them loudly for learners.; Write two-letter action words on a manila card and show it to learners.; Lead learners to read the words.; Let learners write some two-letter action words correctly.', 640),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B1.5.3.1', 'Show an understanding of writing action words', 'B1.5.3.1.2', 'Write three letter action words', 'Write three-letter action words on a manila card and show it to learners.; Lead learners to read the words.; Let learners write some three-letter action words correctly.', 650),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B1.5.3.1', 'Show an understanding of writing action words', 'B1.5.3.1.3', 'Write a sentence with an action word correctly', 'Write a simple sentence on the board. The sentence must have an action word already treated.; Discuss the action word with learners.; Let learners write the sentences with an action word in their exercise books.', 660),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B1.5.4.1', 'Demonstrate knowledge on recognition of qualifying words (adjectives)', 'B1.5.4.1.1', 'Recognise adjectives in sentences', 'Show some concrete objects to learners with different colours and size.; Discuss the objects with them and ask them to describe the objects.; Write down the qualifying words that learners mention on the board.; Write group of words on flashcards and show it to learners.; Lead learners to read the words and recognise the adjectives in the group of words.; Help learners to recognise adjectives. E.g. Colours: red, yellow, blue, etc. Sizes: small, big, etc.', 670),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B1.5.4.1', 'Demonstrate knowledge on recognition of qualifying words (adjectives)', 'B1.5.4.1.2', 'Recognise comparative words/adjectives in short sentences', 'Write simple sentences on flashcards and show it to learners.; Lead learners to read the sentences.; Lead learners to recognise the adjectives in the sentences.', 680),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B1.5.4.1', 'Demonstrate knowledge on recognition of qualifying words (adjectives)', 'B1.5.4.1.3', 'Use comparative words/adjectives in sentences', 'Write the adjectives on a flashcard and show it to learners.; Lead them to read the words aloud.; Form simple sentences with the adjectives.; Ask learners to also use the adjectives to form short sentences.', 690),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Postpositions)', 'B1.5.5.1', 'Exhibit knowledge of usage of postpositions', 'B1.5.5.1.1', 'Use postposition such as in, on, into in context', 'Place some objects at locations in the class and discuss with the learners these locations.; Write the postpositions mentioned during the discussion on the board.; Write the postpositions on a flashcard/board.; Lead learners to read them.; Form simple sentences with the postpositions.; Let learners form their own sentences with the postpositions.', 700),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Postpositions)', 'B1.5.5.1', 'Exhibit knowledge of usage of postpositions', 'B1.5.5.1.2', 'Recognise postpositions in short sentences', 'Write the postpositions on a flashcard.; Lead learners to read them.; Lead learners to recognise postpositions such as in, on, into in short sentences.', 710),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Postpositions)', 'B1.5.5.1', 'Exhibit knowledge of usage of postpositions', 'B1.5.5.1.3', 'Use other forms of postpositions to form short sentences', 'Write the postpositions on a flashcard.; Lead learners to read them.; Lead learners to recognise postpositions in short sentences.; Let learners form their own sentences with the postpositions.', 720),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B1.5.7.1', 'Exhibit knowledge of recognising and spelling simple words correctly', 'B1.5.7.1.1', 'Write two letter words correctly', 'Write two letter words on flashcards and show it to learners.; Lead learners to mention the words.; Put learners in groups and do spelling game or competition among the groups.; Let learners write the two letter words correctly.', 730),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B1.5.7.1', 'Exhibit knowledge of recognising and spelling simple words correctly', 'B1.5.7.1.2', 'Write three letter words correctly', 'Ask learners to say some words they know.; List the words on the board.; Write the three-letter words at one side and say them aloud to learners.; Write some of the three-letter words on flashcards and show it to learners.; Lead learners to mention the words.; Let learners write the three-letter words correctly.', 740),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B1.5.7.1', 'Exhibit knowledge of recognising and spelling simple words correctly', 'B1.5.7.1.3', 'Fill in blank spaces with simple words', 'Write some words on the board.; Lead learners to read the words.; Delete some of the letters of the alphabet from the words and let learners fill in the blank spaces created with the correct letter(s).', 750),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading', 'Building the Love and Culture of Reading', 'B1.6.1.1', 'Demonstrate knowledge by reading short and simple sentences made up of three to four words', 'B1.6.1.1.1', 'Read simple sentences of about three to four words', 'Write sentences made up of three or four words on the board.; Lead learners to read the sentences.; Call learners to read the sentences one by one.; Allow other learners to point to the word /sentence as another learner reads.', 760),
('Basic 1', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading', 'Read Aloud With Children', 'B1.6.2.1', 'Demonstrate knowledge by reading short simple sentences made of words they have learnt', 'B1.6.2.1.1', 'Read simple sentences of about three to four words', 'Write sentences made up of three or four words on the board.; Lead learner to read the sentences.; Call learners to read the sentences one by one.', 770),
('Basic 1', 'History', 'history', 'History as a Subject', 'Why and How We Study History', 'B1.1.1.1', 'Demonstrate understanding of what history is about and how it is part of everyday life', 'B1.1.1.1.1', 'Explain that history deals with past human activities Enquiry route: What event did you witness on your first day at school? Which people took part in the event?', '1. Mention the activity they witnessed on their first day at school; 2. Identify any activity performed in the past which has not been performed again; 3. List any past events they have witnessed; 4. Explain that since those activities were performed in the past, they qualify to be called history; 5. Learners sing a song, recite a rhyme or watch a documentary of any past activity.', 10),
('Basic 1', 'History', 'history', 'History as a Subject', 'Why and How We Study History', 'B1.1.1.1', 'Demonstrate understanding of what history is about and how it is part of everyday life', 'B1.1.1.1.2', 'Describe how sources of historical evidence help us find out about past human activities Enquiry route: where do we get information about our past? Why do we celebrate birthdays and festivals?', '1. Sing songs or recite rhymes related to celebrations such as birthdays, festivals and weddings as part of history.; 2. Sketch/show a video of a scene depicting a birthday, funeral, wedding and festival celebration; 3. Start a birthday partnership/register to make history alive in the classroom. Learners write their date of birth chronologically on a manila card and this should be hanged in the classroom. At the end of every history lesson, the class could refer to these records for an upcoming birthday.; 4. Build an album of themselves and family members, starting with earlier pictures and photographs to resent ones', 20),
('Basic 1', 'History', 'history', 'History as a Subject', 'Community History', 'B1.1.4.2', 'Recount history about their communities', 'B1.1.4.2.1', 'State the similarities and differences between the communities where learners live. Enquiry route: What is unique about your community? How similar/ different is your community from others?', '1. Visit historical sites in town e.g. an old chapel, a post office, a chief’s palace, grooves, forests, wetlands etc.; 2. Learners list the names of historical sites starting with the oldest to the most recent; 3. learners sketch what they have seen on their visit; 4. Compare sketches drawn with pictures of historical sites from other communities; 5. Learners discuss their sketches bringing out similarities and differences in the sites they visited', 30),
('Basic 1', 'History', 'history', 'My Country Ghana', 'How Ghana Got Its Name', 'B1.2.3.1', 'Demonstrate understanding of why Ghana used to be called the Gold Coast’', 'B1.2.3.1.1', 'Explain why, in the past, Ghana was known as the Gold Coast. Enquiry route: Why did the country change its name from the Gold Coast to Ghana? Who proposed the change of name? Why was the new name proposed?', '1. Explain how the name was changed from Gold Coast to Ghana Discuss the English translation of the Portuguese name costa da mina - Gold Coast; 2. Use the internet to locate ancient Ghana empire and the Akan forest regions of Ghana; 3. Discuss the role of Dr J.B. Danquah in linking the civilisations of the ancient Ghana Empire to the Akan of the forest region of Ghana', 40),
('Basic 1', 'History', 'history', 'My Country Ghana', 'How Ghana Got Its Name', 'B1.2.3.1', 'Demonstrate understanding of why Ghana used to be called the Gold Coast’', 'B1.2.3.1.2', 'Recall when the name Ghana came into formal use. Enquiry route: How was the name changed? In which year was the name changed?', '1. Discuss the sequence of events leading to the change of name; 2. Discuss the role of played by parliament and other individuals in the change of name from Gold Coast to Ghana; 3. Dramatise a scene in parliament in changing the name Gold Coast to Ghana; 4. Explain how similarly a new independent country can take on a new name, a new flag, a new leader in a story form. (A resource person could be invited)', 50),
('Basic 1', 'History', 'history', 'My Country Ghana', 'Some Selected Individuals', 'B1.2.5.1', 'Show understanding of significant roles played by Ghanaians from different walks of life', 'B1.2.5.1.1', 'Identify Ghanaians of diverse fields who have contributed significantly to national development including Theodosia Okoh', '– National flag. Amon Kotei – Coat of Arms. Baba Yara – Football for Ghana. Ephraim Amu – Music, Kofi Antubam – Art and craft, Kow Ansah – Film etc. Enquiry route: which individuals have contributed to Ghana’s development? How have they contributed to Ghana’s development? .; 1. Identify Ghanaians of diverse professions who have contributed significantly to national development; 2. Match individuals with their achievements e. g Theodosia Okoh – national flag. Amon Kotei – coat of arms. Baba Yara – football for Ghana. Ephraim Amu- music, Kofi Antubam- art and craft, Kow Ansah – Film etc.; 3. Show and discuss a documentary of significant individuals; 4. Guide learners to study about these individuals using the internet; 5. Role play what learners want to be in future', 60),
('Basic 1', 'History', 'history', 'Europeans in Ghana', 'Arrival of Europeans', 'B1.3.1.1', 'Show understanding of Europeans who came to Ghana', 'B1.3.1.1.1', 'Explore which Europeans came to Ghana Enquiry Route: Which Europeans came to Ghana? Which country came first? Where did they first settle?', '1. Identify the European countries whose citizens came and settled in Ghana - Portugal, Britain, France, Sweden, Germany, (Brandenburg) Denmark, Norway, Netherlands; 2. Arrange the Europeans which they came to Ghana in the order which they came (starting with those who came first); 3. Locate each of these countries on the world map using the internet.; 4. Find out where each country first settled in Ghana (From parents, museums etc.)', 70),
('Basic 1', 'History', 'history', 'Independent Ghana', 'The Republics', 'B1.6.1.1', 'Demonstrate understanding of the presidents that have ruled Ghana since 1960', 'B1.6.1.1.1', 'Identify the Presidents Ghana has had since 1960 Enquiry route: Who was Ghana’s first President? Who ruled Ghana from 1960- 2016?', '1. Name the presidents of Ghana since 1960.; 2. Match pictures of Ghana’s presidents with their names (Create an album with the pictures). Match the names of presidents of Ghana with their dates of tenure (Add the names to their pictures).; 3. Put learners in groups to create a gallery station on the following lines. a. Select a picture of one of the presidents b. Display the picture of the selected president on a large cardboard c. Write the name of the president below the picture d. Add the length of tenure of the president; 4. ** Invite learners to visit the gallery station and talk about each group’s presentation', 80),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number: Counting, Representation, Cardinality & Ordinality', 'B1.1.1.1', 'Describe numbers and the relationship between numbers 0 to 100', 'B1.1.1.1.1', 'Use number names, counting sequences and how to count to find out “how many?”', 'E.g.; 1. Count by 1s (forwards and backwards) between two given numbers between 0 and 100; or by 2s and 10s; Identify and correct errors or omissions in counting or skip counting sequences E.g.; 2. Count to answer “how many?” questions about as many as 100 objects arranged in a line, a grid or a circle; Show that the count of a group of up to 100 objects does not change regardless of the order in which the objects are counted or the arrangement of the objects E.g.; 3. Estimate the number of objects in a small group (up to 100) and describe the estimation strategy used; Select an appropriate estimate among all those given for a group of up to 100 objects and justify the choice E.g.; 4. Represent the number of objects in a group with a written numeral 0 to 100. Use ordinal numbers to describe the position of objects up to 10th place', 10),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number: Counting, Representation, Cardinality & Ordinality', 'B1.1.1.1', 'Describe numbers and the relationship between numbers 0 to 100', 'B1.1.1.1.2', 'Identify numbers in different positions around a given number (0', '– 100) E.g.; 1. Display a number chart with numbers multiples of say 4 between 0 and 100 and have learners identify numbers in different positions around a given number. Put learners in convenient groups and give each group a number grid and have them identify numbers in different positions around a chosen number. 4 8 1 16 18 11 28 44 69 67 76 96', 20),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number: Counting, Representation, Cardinality & Ordinality', 'B1.1.1.1', 'Describe numbers and the relationship between numbers 0 to 100', 'B1.1.1.1.3', 'Use number names and non-standard units for measuring (lengths and volumes) to count to find out “how long or how much?”…up to 100', 'E.g.; 1. Have learners use their feet, hand-span and referent materials to find how long a table, window and door frames are etc., by counting the number of times their feet, hand-span and referent materials are able to do this E.g.; 2. Have learners use empty containers such as bottles, cups etc. to determine the capacity of other bigger containers by counting to find how much (the number of times) the bottles, cups etc. are able to do this; 8; 18; 44; 76', 30),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number: Counting, Representation, Cardinality & Ordinality', 'B1.1.1.1', 'Describe numbers and the relationship between numbers 0 to 100', 'B1.1.1.1.4', 'Use comparative language to describe the relationship between quantities/numbers up to 100 using place value and the number line', 'E.g.; 1. Use 1-to-1 correspondence or matching to solve problems that involve comparing 2 sets having between 1 to 100 objects and explain how he/she solved the problem (finding which set has more or less, which groups have the same as) E.g.; 2. Use the terms "more than", "less than" or "the same as" when comparing two groups having between1 to 100 objects E.g.; 3. Put groups between 1 to 50 objects in increasing or decreasing order and justify his/her answer or explain what he/she did to find the answer E.g.; 4. Identify numbers and groups of objects that are that are 1 more or less than a number (for numbers 1 to 100 E.g. 5 Use the number line to compare and order whole numbers from 0 to 100', 40),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number: Counting, Representation, Cardinality & Ordinality', 'B1.1.1.1', 'Describe numbers and the relationship between numbers 0 to 100', 'B1.1.1.1.5', 'Represent the comparison of two number up to 100 using the symbols “>, < or =”', 'E.g.; 1. Use the terms "more than", "less than" or "the same as" when comparing two numbers between1 to; 50. E.g.; 2. Use the symbols ">", "< " or "=" when comparing two numbers between1 to 50', 50),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number: Counting, Representation, Cardinality & Ordinality', 'B1.1.1.1', 'Describe numbers and the relationship between numbers 0 to 100', 'B1.1.1.1.6', 'Describe the relationship between quantities/numbers up to 100', 'E.g.; 1. Use one-to-one correspondence, matching or counting to identify whether the number of objects in one group of up to 20 objects is greater than, less than or equal to the number of objects in another; describe the relationship between the two groups or numerals using the terms greater than, less than, or equal to E.g.; 2. Build a group that has more than, less than, or the same number as a given set E.g.; 3. Demonstrate an understanding of the relative size of numbers up to 100 by: - Order groups of 1 to 20 objects and then a small set of numerals between 1 and 20, and justifying the arrangement - Describe the relative size of numbers up to 100 (i.e., say whether one number is a lot or a little bigger or smaller than another, or 5 more than another number); - Place given numerals between 0 and 50 on a number line that has 0, 5 10 and 20 indicated as benchmarks - Act out and solving problems (pictures and words) that involve comparing quantities (i.e., Johnson has 3 mangoes, Adwoa has; 7. what can you say?)', 60),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B1.1.2.1', 'Develop a conceptual understanding of addition and subtraction', 'B1.1.2.1.1', 'Demonstrate understanding of addition as joining and finding how many altogether and subtraction as separating and finding how many left; numbers 0 to 20', 'E.g.; 1. Acting out a given story problem presented orally. For instance, - Sena has 8 bottle caps. She takes 5 more bottle caps from Kofi. How many bottle caps does Sena now have? - Kojo has 15 pencils. He gave 7 to Ato. How many pencils are left?; Indicating if the scenario in a story problem represents an addition or a subtraction and justifying the answer E.g.; 2. Creating a story problem for subtraction or addition or for a given number sentence (+ and – within; 20) - Daniel’s family have 6 electric bulbs in the house. Two of the bulbs are not working. How many bulbs can Daniel’s family use?', 70),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B1.1.2.2', 'Demonstrate an understanding of the concept of equality', 'B1.1.2.2.1', 'Use objects and pictorial models to solve word problems involving joining, separating and comparing sets within 20 and unknowns as any one of terms in problems such as 9 +7 = [], 13 +[] =19 and 14-[]=3', 'E.g.; 1. Explaining that = means “the same as’ - Identifying if two quantities or groups of objects are equal or not and justifying answers - Using the symbol = to record equal relationships (e.g., 3 = or + = ) - Representing a pictorial or concrete equality in symbolic form (e.g., represent + = as 3 + 2 =; 5) E.g.; 2. Use a symbol ( ____ ) to represent the unknown in an addition or subtraction statement.', 80),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B1.1.2.2', 'Demonstrate an understanding of the concept of equality', 'B1.1.2.2.2', 'Use relationship between addition and subtraction to demonstrate understanding of equality for numbers within 20', 'E.g.; 1. Demonstrate an understanding of the relationship between addition and subtraction by: transforming a subtraction as an equivalent addition and vice versa (For example, subtracting eight from 10 (10 –; 8) is the same as identifying the number that must be added to 8 to make; 10) 10 − 8 = What? Means 8 + What? = 10', 90),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B1.1.2.2', 'Demonstrate an understanding of the concept of equality', 'B1.1.2.2.3', 'Generate and solve word problem situations when given a number sentence involving addition and subtraction of numbers within 20', 'E.g. Write addition and subtraction problems, learners in their groups discuss and generate word problems to match the number sentences', 100),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B1.1.2.3', 'Demonstrate fluency with addition and subtraction- relationships', 'B1.1.2.3.1', 'Use strategies for solving basic addition facts (and related subtraction fact) to10. (Note: The focus is on developing strategies to find answers, not memorising number facts. That comes in P2 and P3)', 'E.g.; 1. Naming the number that is 1 more, 2 more, 1 less, or 2 less than a number given by the teacher or another pupil (for numbers up to 20 only) E.g.; 2. Naming the double of a number to 10 E.g.; 3. Identifying 10 more or less than a number between 0 and 20, and eventually between 0 and 100 E.g.; 4. Identifying combinations to 5 or 10 (i.e., given a number, quickly identify how many more must be added to get 5 or 10)', 110),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B1.1.2.4', 'Apply strategies for adding and subtracting to 20', 'B1.1.2.4.1', 'Use counting on, counting down and missing addend strategies for adding and subtracting within 20', 'E.g.; 1. Relating counting to addition (i.e., recognizing that adding 2 is the same as counting on; 2) E.g.; 2. Counting on (i.e., for 5 + 3, start at 5 and count on 3 places… 6, 7,; 8. The answer is 8.) E.g.; 3. "Making 10s" (i.e., if 7 + 2 + 3, do 7 + 3 = 10 first then add; 2. The answer is; 12. Or if given 7 + 2 + 3, change the order of the addends to 7 + 3 + 2 to produce combinations that add to 10; Or if given 2 + 6 + 4, add the two last addends first to produce 2 + 6 + 4 = 2 + 10 = 12 Or if given 8 + 3, change question to 8 + 2 + 1 = 10 + 1 =; 11) E.g.; 4. "Making doubles" (i.e., if 5 + 4, do 4 + 4 = 8 then add; 1. The answer is; 9. Or if given 6 + 7, change question to 6 + 6, which give 12 then add; 1. The answer is 13). Relating subtraction to counting down (i.e., Recognizing that subtracting 3 is the same as counting down; 3) (i.e., for 15 - 3, start at 15 and count on 3 places… 14, 13,; 12. The answer is 12.) E.g.; 5. Relating subtraction to comparison or finding the difference (Recognizing that subtracting 5 from 8 is the same as ‘ 5 is how many less than 8; or ‘8 is how many more than 5; E.g.; 6. "Using addition to subtract" or re-writing as addition sentence and finding the missing addend (i.e., if given 7 - __ = 5, change the question to the addition 5 + ___ =; 7. The answer is 2, so 7 - 2 =; 5. 7 − What? = 5 means 5 + What? = 7; Or if given 8 - 6 = ___ change question to 6 +__ = 8. The answer is 2, so 8 - 6 = 2). That is, 8 − 6 = What? means 6 + What? = 8', 120),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B1.1.2.4', 'Apply strategies for adding and subtracting to 20', 'B1.1.2.4.2', 'Solve one-step word problems involving addition and subtraction within 20 using a variety of strategies', 'E.g.; 1. Use a variety of strategies (objects, drawings, mental strategies, counting on, doubles etc.) to solve addition word problems to 20 involving adding to, putting together – and with unknowns in all positions. - Ama has 10 mangoes and receives 3 more mangoes. How many mangoes does she have altogether? E.g.; 2. Use a variety of strategies (objects, drawings, mental strategies, counting down, etc.) to solve subtraction word problems to 20 involving taking from, taking apart and comparing – and with unknowns in all positions. - Kojo has 15 pencils. He gave 7 to Ato. How many pencils are left? - Kafui had 5 pencils. Kwame had 3 pencils. How many more pencils did Kafui have than Kwame?', 130),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Fractions', 'B1.1.3.1', 'Develop an understanding of halves using concrete and pictorial representations [Exclude notation here]', 'B1.1.3.1.1', 'Understand the fraction one-half as the quantity obtained by taking 1 part when a whole is partitioned into two equal parts', 'E.g.; 1. Use concrete objects to explain the fraction half as the quantity obtained by taking 1 part when a whole object is partitioned into two equal parts E.g.; 2. Use pictorial representations to explain the fraction half as the quantity obtained by taking 1 part when a whole object is partitioned into two equal parts E.g.; 3. Use pictorial representations to help learners sort One whole one half fractions into those that are halves and those that are not halves', 140),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Fractions', 'B1.1.3.1', 'Develop an understanding of halves using concrete and pictorial representations [Exclude notation here]', 'B1.1.3.1.2', 'Count in halves using concrete and pictorial representations of halves', 'E.g.; 1. Show several halves of concrete objects (like half oranges, half piece of stick, half piece of card, etc. and have them count them in halves (using the language one-half, two-halves, three-halves, etc.) E.g.; 2. Show learners several pictorial representations of halves and have them count (using the language one-half, two-halves, three-halves, etc.)', 150),
('Basic 1', 'Mathematics', 'maths', 'Number', 'Money', 'B1.1.4.1', 'Identify coins, their values and the relationships among them in order to recognize the need for monetary transactions', 'B1.1.4.1.1', 'Recognise Ghanaian coins by name, including one pesewa, five pesewas, ten pesewas, twenty pesewas, fifty pesewas and one cedi by value and describe the relationship among them', 'E.g.; 1. Display the various coins currently being used for transaction in Ghana and initiate discussion on the need for monetary transaction. Learners touch feel and say the features of each coin E.g.; 2. Introduce the one pesewa, five pesewas, ten pesewas, twenty pesewas, fifty pesewa and guide learners learn to identify and recognize the money by name and value E.g.; 3. State the relationship between 2p and 10p; 5p and 10p; 2p and 20p; 1p and ¢1, 10p and ¢1', 160),
('Basic 1', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationship', 'B1.2.1.1', 'Recognize, create, extend and describe non- numerical and simple numerical patterns', 'B1.2.1.1.1', 'Demonstrate an understanding of repeating patterns with 2 to 4 repeating elements', 'E.g.; 1. Identifying, duplicating, extending or creating a simple - number patterns (1, 2, 3, 4, 1, 2, 3, 4… ___) with 2 to 4 repeating elements, - shape patterns (e.g. ★ ★ ...) with 2 to 4 repeating elements, - sound (clap, clap, snap, snap, clap, clap, snap, snap…) with 2 to 4 repeating elements, or - action patterns (stand up, sit down, clap, stand up, sit down, clap…) with 2 to 4 repeating elements. - E.g.; 2. Identifying and describing errors or missing elements in number, shape, sound or action patterns with 2 to 4 repeating elements (e.g., - - 2 4 6 2 ___; 6) E.g.; 3. Representing a repeating sound or number pattern as shape pattern or vice versa (e.g., represent 1, 2, 1, 2 as clap, snap, clap, snap or as ★ ★ ) E.g.; 4. Identifying and describing patterns in and outside the classroom (in a song, in a fabric, etc.) For instance, use patterns in Kente as examples of repeating patterns.', 170),
('Basic 1', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B1.3.1.1', 'Analyse attributes of two- dimensional shapes and three-dimensional objects to develop general concept about their properties', 'B1.3.1.1.1', 'Distinguish between attributes that define a two- dimensional figure or three-dimensional figure and attributes that do not define the shape Display 2D cut out shapes and 3D objects and have learners', 'E.g.; 1. Identify 2D shapes (triangles, squares, rectangles, circles) on the surfaces of 3D objects (cubes, cylinders, spheres, rectangular prisms) in the classroom or beyond; Identify what features define a shape or an object (e.g. triangles are closed and have three sides) and other features (colour, orientation or size) E.g.; 2. Sort a given set of 2D shapes and 3D objects using a given single feature or criteria (size, shape, etc.) and explain the sorting rule, feature or criteria used to sort them; Describe the difference between two given pre-sorted sets of familiar 3D objects or 2D shapes and the feature or criteria used to sort them E.g.; 3. Identify 3D objects in the environment that have parts similar to a given 2D shape (e.g., find the parts of a can or bucket that are similar to a circle) E.g.; 4. Create a composite 2D shape from 2D shapes (i.e., build a new shape using triangle, circles, rectangles, or squares, or build a rectangle using squares or a square using triangles etc.) and describe it. (Make several of the logic block set below with card or plywood and paint them)', 180),
('Basic 1', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B1.3.1.1', 'Analyse attributes of two- dimensional shapes and three-dimensional objects to develop general concept about their properties', 'B1.3.1.1.2', 'Identify three-dimensional shapes, including spheres ones, cylinders, rectangular prisms (including cubes), and triangular prisms and describe their attributes using formal geometric language', 'E.g.; 1. Sort a given set of 3D shapes using a given single feature or criteria (size, shape, etc.) and explain the sorting rule, feature or criteria used to sort them E.g.; 2. Describe the difference between two given pre-sorted sets of familiar 3D shapes and the feature', 190),
('Basic 1', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B1.3.1.1', 'Analyse attributes of two- dimensional shapes and three-dimensional objects to develop general concept about their properties', 'B1.3.1.1.3', 'Identify two-dimensional shapes, including circles, triangles, rectangles and squares as special rectangles, rhombuses and hexagons and describe their attributes using formal geometric language', 'E.g.; 1. Sort a given set of 2D shapes using a given single feature or criteria (size, shape, etc.) and explain the sorting rule, feature or criteria used to sort them E.g.; 2. Describe the difference between two given pre-sorted sets of familiar 2D shapes and the feature', 200),
('Basic 1', 'Mathematics', 'maths', 'Geometry and Measurement', 'Position /Transformation', 'B1.3.2.1', 'Describe the position of objects in space', 'B1.3.2.1.1', 'Tell the position of objects relative other objects in space using words such above, below, to the right etc', 'E.g.; 1. Learners tell their sitting position relative to other children in the classroom. For example, Yaw is on the third line (row), three places from Ama and to the left of Kwesi', 210),
('Basic 1', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass and Capacity', 'B1.3.3.1', 'Demonstrate an understanding of Measurement', 'B1.3.3.1.1', 'Develop an understanding of measuring as a process of comparing pairs of items using words such as smaller, longer, thinner, heavier, bigger etc. E.g.1', 'Learners bring together pairs of objects on the same flat surface to compare to find out which is taller', 220),
('Basic 1', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Interpretation, Presentation and Analysis', 'B1.4.1.1', 'Organise, represent and interpret data', 'B1.4.1.1.1', 'Organise and represent (using pictures/objects) data with up to three categories', 'E.g.; 1. Have a picture of learners in front of the class and ask the learners to use two different pictures/objects to represent the number of males and females. Repeat with pictures of animals E.g.; 2. Using a one-to-one correspondence to solve simple problems (i.e. how many altogether, how many more or less) problems requiring interpretation of the concrete representation of pictures as in E.g. 1 above', 230),
('Basic 1', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Interpretation, Presentation and Analysis', 'B1.4.1.1', 'Organise, represent and interpret data', 'B1.4.1.1.2', 'Organise a given set of data into three categories, find the total number of data points and determine how many are in each category and compare the number in any two category', 'E.g.; 1. Learners use tally charts with data relevant to their daily lives (e.g. favourite drinks, eye colour , pets etc) to analyze and compare data in a picture graph E.g.; 2. Learners construct pictures graphs in groups as well as individually based on data given them', 240),
('Basic 1', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B1.1.1.1', 'Explain who the Creator is', 'B1.1.1.1.1', 'Explore God’s Creation', 'In groups, learners discuss who the creator is. - He is God, the originator of all things. - He provides all our needs: air, food, water, life, etc.', 10),
('Basic 1', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B1.1.1.1', 'Explain who the Creator is', 'B1.1.1.1.2', 'Mention the names of some of the things God created', 'Engage learners with pictures, charts, video clips and songs showing some of the things God created: humankind, animals, trees, rivers, the sea and mountains.; Let learners draw, colour and model some of the things God created.; Help learners to role play, recite rhymes and sing songs about some of the things God created.', 20),
('Basic 1', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B1.1.1.1', 'Explain who the Creator is', 'B1.1.1.1.3', 'Examine some attributes of God', 'In groups, guide learners to talk about the attributes of God.; Engage learners with pictures, charts, video clips, songs and role play to demonstrate attributes of God showing: love to one another, truthfulness, kindness, patience, mercy, etc. at home, school and community.; Let learners role play the following activities: - home: family members caring for one another, - school: teachers and learners demonstrate care and love among themselves and - community: visits to the hospital and orphanage, etc.', 30),
('Basic 1', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Religious Worship in the Three Major Religions in Ghana', 'B1.2.1.1', 'Demonstrate the understanding of religious worship', 'B1.2.1.1.1', 'Name the three main types of worship in Ghana', 'Show pictures, video clips of people worshipping among the three main religions in Ghana. - Christian worship, - Islamic worship and - Traditional worship.; Let learners role-play the act of worship in the three main religions in Ghana.', 40),
('Basic 1', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Religious Worship in the Three Major Religions in Ghana', 'B1.2.1.1', 'Demonstrate the understanding of religious worship', 'B1.2.1.1.2', 'Recite religious passages and sing religious songs', 'Show pictures, video clips, etc. of songs and recitations from the three main religions.; Let learners sing and recite texts from the three main religions: - The Lord’s Prayer, Psalm 23 (Christian), - Al- Fãtihah (Islamic) and - any recital from the traditional religion-sacred myths, riddle, proverbs, etc. (Traditional).', 50),
('Basic 1', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Religious Worship in the Three Major Religions in Ghana', 'B1.2.2.1', 'Demonstrate the understanding of religious worship', 'B1.2.2.1.1', 'Describe religious festivals in Ghana', 'Guide learners to mention festivals celebrated in the three religions. - Christian: Christmas, Easter, etc. - Islamic: Eid-ul-Fitr, Eid-ul-Adha, etc. - African Traditional Religion (ATR): Odwira, Damba, Homowo, Hogbetsotso, Fetu AfahyƐ, etc.; -', 60),
('Basic 1', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'Birth of the Leaders of the three Major Religions in Ghana', 'B1.3.1.1', 'Narrate the birth stories of the leaders of the three main religions', 'B1.3.1.1.1', 'Narrate the stories of the birth of religious leaders', 'Show pictures and video clips depicting the birth of the religious leaders: Christian, Islamic and ATR.; Let learners tell stories about the birth of the religious leaders.; Let learners dramatise the birth of the religious leaders.', 70),
('Basic 1', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B1.4.1.1', 'Show an appreciation of the roles of the family and community in their daily lives', 'B1.4.1.1.1', 'Identify the role of the individual members of the family', 'Let learners, in groups, talk about their roles and roles of their parents in the family: - Parents: Provision of shelter, food, security and education, - Children: running errands, performing house chores, etc.; Let learners role-play the functions of the various members in the family, e.g. Learners play the role of a father, mother, etc.', 80),
('Basic 1', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B1.4.1.1', 'Show an appreciation of the roles of the family and community in their daily lives', 'B1.4.1.1.2', 'Explain the role of the community in the upbringing of its members', 'Let learners, in groups, talk about the role of the community in the upbringing of its members through education, discipline, counselling, etc.; Let learners dramatise or role-play the roles of members of the community in the upbringing of its members through education, discipline, counselling, etc.', 90),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B1.1.1.1', 'Show understanding of the physical features and life processes of living things and use this understanding to classify them', 'B1.1.1.1.1', 'Observe and describe different kinds of things in the environment', 'Go on nature walk to observe things in the environment (e.g. Plants, animals, plastics and stones. The things should come from the classroom and the school environment; Work in groups to describe the different kinds of things; Elaborate on the learners’ ideas to find out why they need to know about the characteristics of different things in their environment; Sort things into living and non –livings based on common characteristics; Watch videos/pictures of different kinds of living and non-living things in the environment.', 10),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B1.1.1.2', 'Understand the differences between living things, non-living things and things which have never been alive', 'B1.1.1.2.1', 'Identify and name animals and plants in their locality', 'Watch pictures or videos on animals and plants; With guidance, learners identify the local names of plants and animals seen in the videos and pictures; Learners come out with the local names of other plants and animals not seen in the video/pictures using the ‘’think-pair-share’’; Draw and colour any local plant or animal; Compare their drawings and identify the type of animal or plant drawn through a peer activity', 20),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B1.1.1.2', 'Understand the differences between living things, non-living things and things which have never been alive', 'B1.1.1.2.2', 'Know the basic needs of living things (food, water and air)', 'Give some examples of living things (for example things that eat/drink, move, grow and produce young ones).; Work in pairs to identify the basic needs of living things (e.g. food, water, air, shelter, appropriate warmth).; Elaborate on learners’ ideas to guide them to brainstorm on the importance of basic needs of living things.', 30),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B1.1.1.2', 'Understand the differences between living things, non-living things and things which have never been alive', 'B1.1.1.2.3', 'Describe the differences between living and non-living things', 'Watch a video or observe pictures of living and non- living things or go on an observational trip around the school community to observe living and non-living things.; Learners mention the names of the specific living things and non-living things observed.; Describe the differences between living and non- living things using think –pair share (focus on differences in movement, growth, feeding, reproduction).; Give reasons for grouping things into living and non-living.; Learners reflect on what they have learnt about living and non- living things and answer questions like: What are examples of living things? What are examples of non- living things? In what ways are living things different from non-living things? Come out with differences between non-living things and things that are dead.', 40),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B1.1.2.1', 'Recognise materials as important resources for providing human needs', 'B1.1.2.1.1', 'Identify and name a variety of everyday materials in their immediate environment', 'Teacher engages learners with questions about metals, wood, plastics, soil, glass, textiles, water and stone they see around the playground and other places outside the school or engages learners to go on nature walk and observe and collect materials present in their environment.; In groups, learners observe, sort, identify and name materials collected such as wood, plastic, soil, metals glass, textile, water and stone; and explain the basis of their classification.; Reflect on what they have learnt and relate the lesson to everyday uses of the materials. NB: Teacher should build a stock of materials into a science corner to annul any shortages.', 50),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B1.1.2.1', 'Recognise materials as important resources for providing human needs', 'B1.1.2.1.2', 'Describe and group materials by their appearance (shape, size, colour, texture, mass)', 'Collect different materials from the school environment and bring them to class.; Learners describe the appearance of the materials (in terms of colour, size, feel, length etc.).; Group materials based on their observable properties such as shape, size (big/small), colour, texture (‘rough’, ‘smooth’, ‘sticky’ and ‘grainy’), mass (heavy / light).; Draw and colour several objects/ materials based on their appearance such as colour and shape.; Display their drawings for class observation and talk about them.; Relate the lesson with everyday experiences (appearance and properties of common items).', 60),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B1.1.2.2', 'Know that substances can exist in different physical state (Solid, Liquid, Gas). Many substances can be changed from one state to another by heating or cooling', 'B1.1.2.2.1', 'Identify and classify materials as solid, liquid or gas', 'Learners explore and list materials they see in their environment.; In groups, sort the materials into solid, liquid or gas. NB: to demonstrate the presence of gas, learners can use paper cards /sheets of paper and wave them across their faces.; In groups learners sort different substances into the solid, liquid or gaseous states with reasons.; Each group presents their work to the whole class for discussions.; Learners answer the following questions: What makes a solid different from a liquid? How is a liquid different from a gas?; Learners can be engaged in more activities to investigate and identify substances in the solid, liquid and gaseous states. E.g. inflating balloon, breathing in and out.', 70),
('Basic 1', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B1.1.2.3', 'Understand mixtures, the types, their formation, uses and ways of separating them into their components', 'B1.1.2.3.1', 'Demonstrate understanding that a mixture is two or more objects or materials put together', 'Present several different materials to the groups such as gari, sand, water, saw dust, milo, salt, sugar, milk powder, etc.; Learners work in groups to combine the materials in any proportion, two at a time, e.g. gari and sand; milo and milk powder; sugar and water etc. and describe what happens in each case.; Learners find-out whether the products they have formed are the same as the individual materials.; In groups, learners give names to the combinations they have formed.; Provide learners with samples of mixtures, e.g. A mixture of different coloured beads, a mixture of chocolate pellets of different colours to separate. NB: The idea is for them to understand that when they mix two or more things together, they form a mixture and that no new thing forms even though the starting and ending substances may look different from each other.', 80),
('Basic 1', 'Science', 'science', 'Cycles', 'Earth Science', 'B1.2.1.1', 'Recognise that some events in our environment occur recurrently', 'B1.2.1.1.1', 'Explain that some natural phenomena, such as day and night, occur repeatedly', 'Learners can be engaged in an activity that explains cyclic movement. (The second hand of an analogue clock, merry-go-round and circular cards, musical chairs could be used).; Relate this activity to the occurrence of day and night and explain that the appearance of the Sun, Moon and stars follow a cyclic pattern.; Let learners suggest other events in their environment that happen over and over again in a cycle. For example, dry and wet seasons.; Learners make sketches displaying events that take place in the day and those that take place in the night.', 90),
('Basic 1', 'Science', 'science', 'Cycles', 'Earth Science', 'B1.2.1.2', 'Recognise the relationship between the Earth and the Sun', 'B1.2.1.2.1', 'Know that the sun is the main source of light to the Earth', 'Engage learners with a number of questions to enable them explore where we get light, e.g. What does the sun look like? Where is the sun located? Do you see clearly or otherwise when the sun is out?; Display various sources of light such as torch, candles, matchstick, and lantern.; Brainstorm with learners to come out with one thing which is common to all the items you have displayed.; Engage learners to mention sources of light in their environment (i.e. sun, moon, other stars, torch, lantern, electric bulbs and others).; Learners brainstorm to come out with the main source of light by considering the biggest source of light which makes them see clearly in the day time.; Learners use paper to design the sun as a source of light to the earth', 100),
('Basic 1', 'Science', 'science', 'Cycles', 'Earth Science', 'B1.2.1.3', 'Show understanding of the roles of condensation, evaporation, transpiration and precipitation in the hydrological cycle', 'B1.2.1.3.1', 'Observe the disappearance of mist and pools of water after rains', 'Let learners observe the disappearance of mist and run-off water after rains and come and talk about it in class. (Note: This activity is to be carried out after rains).; Engage learners to predict where mist and run-off water go after rains and assist them to understand that they evaporate. NB: Mists evaporates but run-off water either flows into surface water bodies or collects as stagnant pools of water. Run-off water takes a longer time to evaporate', 110),
('Basic 1', 'Science', 'science', 'Cycles', 'Earth Science', 'B1.2.1.4', 'Recognise water and air as important natural resources', 'B1.2.1.4.1', 'Identify sources and uses of water in the home and at school', 'Ask learners where they get water (sources of water) at the home, community and school.; In a participatory manner, learners come out with sources of water in the home and at school; Show or draw pictures depicting different sources of water such as bore-holes, rivers, wells and the sea; Discuss the various uses of water at their homes, school and community.; Learners demonstrate several uses of water, e.g. washing of face and hands, drinking and preparing beverages, rinsing of utensils, watering of flowers.; Use local materials to create different sources of water in an outdoor activity. E.g. artificial wells, rivers, rainfall and tap', 120),
('Basic 1', 'Science', 'science', 'Cycles', 'Earth Science', 'B1.2.1.4', 'Recognise water and air as important natural resources', 'B1.2.1.4.2', 'Demonstrate the existence of air in the environment', 'Engage learners in a number of games/ fun activities that demonstrate the existence of air, e.g. Waving a piece of paper across the face, leaving inflated balloons in an open space, watching a hoisted flag, observing the leaves of a plant in the school, closing their mouths and then taking a deep breath, asking learners to fan themselves or sit in front of a working fan.; Learners talk about their observations in each case, e.g. explain what causes the leaves and hoisted flag to move.; Ask learners to outline uses of air in their lives. e.g. whistling, blowing of trumpets, flying kites, sailing of boats.; Summarise the lesson by explaining to learners that air is everywhere.', 130),
('Basic 1', 'Science', 'science', 'Cycles', 'Life Cycles of Organisms', 'B1.2.2.1', 'Demonstrate understanding of the life cycle of plants', 'B1.2.2.1.1', 'Examine the structure of plants', 'Assist learners to uproot young plants from the school environment and bring them to class; Learners examine the external parts of the plants (using hand lens if available),; Draw the external parts and display drawings for discussion.; Create weed albums using leaves of different plants', 140),
('Basic 1', 'Science', 'science', 'Cycles', 'Life Cycles of Organisms', 'B1.2.2.1', 'Demonstrate understanding of the life cycle of plants', 'B1.2.2.1.2', 'Observe different kinds of seeds', 'Provide learners with different kinds of seeds (e.g. orange, pawpaw, mango, bean seeds, shea nut).; Learners examine the external parts of different seeds, draw and display them for discussion.; Through a matching game, learners identify different fruits and their seeds.', 150),
('Basic 1', 'Science', 'science', 'Systems', 'The Human Body Systems', 'B1.3.1.1', 'Recognise that different parts of the human body work interdependently to perform a specific function', 'B1.3.1.1.1', 'Identify the external human body parts by their appropriate names (', 'e.g. eyes, ears, mouth, nose, legs, hands, shoulders, knees, fingers, toes and chest); Use songs to get learners to name the parts of their bodies e.g., “my head, my shoulders, my knees and toes” or “show me your head, show me your eyes”.; Use realia, videos or charts/pictures to guide learners identify the external parts of the human body.; Learners draw a human body and use a colour of their choice to colour their drawing.; Learners can trace an outline of the human body on a cardboard or paper.; Learners display their work for discussion', 160),
('Basic 1', 'Science', 'science', 'Systems', 'The Human Body Systems', 'B1.3.2.1', 'Show understanding and appreciation of the interactions and interdependencies of organisms in an ecosystem', 'B1.3.2.1.1', 'Know the places where living things live (land, air, and water)', 'Learners observe different habitats around the school, e. g. a tree which houses some birds and insects, a bush or a pond.; Observe videos or pictures of places where living things live e.g. a marshy area, forest, a pond etc.; Display pictures of air, water and land habitats with different organisms.; Learners come out with the names of the living things found in the three habitats (living places) in the video, pictures or through the nature walk.; Engage learners to draw organisms in their natural homes.', 170),
('Basic 1', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B1.4.1.1', 'Demonstrate understanding of the concept of energy, its various forms and sources and the ways in which it can be transformed and conserved', 'B1.4.1.1.1', 'Understand energy and give examples of its uses', 'Learners talk about why they eat food every day; Guide learners to undertake activities that involve the use of energy. E.g. clapping of hands, lighting of a candle or torch, or switching on the light in the classroom.; Assist learners to come-out with the meaning of energy.; Ask learners to brainstorm on what happens when a car runs short of fuel.; Summarise the learners’ responses by explaining to them that energy is what enables us to do work.', 180),
('Basic 1', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B1.4.1.2', 'Show understanding of the concept of heat energy in terms of its importance, effects, sources and transfer from one medium to another', 'B1.4.1.2.1', 'Explain the terms hot and cold', 'Ask learners: What types of things are usually hot? What types of things are usually cold?; Display substances that are hot or cold (e.g. hot tea, ice cream, ice block, hot water, water at room temperature, cold water.; Learners sort the items into hot and cold in groups.; Show learners a hot item (learners should not touch) to differentiate it from warm items.; Learners compare the samples in terms of warmth (by touching/feeling the provided samples).; Learners talk about how we keep hot things hot and cold things cold for a long time.; What will happen if an object is placed in the sun?;  Tell how substances placed in a fridge feel when touched  Learners explore other ways of making things warm (For example, putting them in the sun, touching a phone that has just been charged Precaution: Unplug the phone before using it', 190),
('Basic 1', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B1.4.2.1', 'Demonstrate knowledge of generation of electricity, its transmission and transformation into other forms of energy', 'B1.4.2.1.1', 'Know the importance of electricity and identify common household appliances that require electricity to work', 'Learners mention items in their homes that use electricity.; Alternatively show them videos/drawings of items that use electricity.; Put learners into groups and give each group flashcards of items that use electricity and those that do not.; Assist learners to sort the items into two groups i.e, ‘use electricity’ and ‘does not use electricity’.; Let learners match the items mentioned with their functions, e.g. washing machine is the item used for washing, the item used to play music is the sound system.; Guide learners through questioning to understand why all such appliances are connected to a source of electricity.; Learners brainstorm on how daily living without electricity will affect our homes, schools and industries.; Summarise lesson by explaining that electricity is a form of energy thus it enables electrical items to work.; Learners talk about the importance of electricity in the home.', 200),
('Basic 1', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B1.4.2.2', 'Demonstrate knowledge of generation of electricity, its transmission and transformation into other forms of energy', 'B1.4.2.2.1', 'Know examples of common electronic devices and their uses', 'Display real or pictures of electronic devices such as mobile phones, wrist watches, cameras and torches.; Let learners identify the devices displayed.; Engage learners in an activity to match the devices with their uses.; Assist learners to model any one electronic device of their choice using appropriate materials. (Blu tack, clay or cardboard).', 210),
('Basic 1', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B1.4.3.1', 'Know that movement is caused by applied forces due to the release of stored energy', 'B1.4.3.1.1', 'Explain force as a pull or a push on an object', 'Show pictures or ask learners to mention activities in the home and the community that involve a push or a pull, e.g. donkey pulling a cart, people pushing a car, people drawing water from a well; Take learners outside the classroom to participate in several games or activities involving pull or a push force, e.g. kicking and throwing of balls, pushing and pulling of boxes, tables and chairs and tug of war; Learners observe the movement of things, e.g. leaves, plants, balloons and other materials under the influence of the wind. Pictures and videos can be used. Let them discuss other actions that will cause objects to move.; Guide learners to brainstorm on why the pushed objects move; Elaborate on learners’ responses to explain that a push or a pull causes objects to move. Such a push or pull is termed as a force; Engage children in drawing activities involving pushing and pulling e.g. a friend pushing an object', 220),
('Basic 1', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B1.4.3.2', 'Recognise some simple machines used for making work easier, analyse their advantages and know their uses. E.g. levers, inclined planes and pulleys', 'B1.4.3.2.1', 'Understand what simple machines are and cite common examples', 'Engage learners in an activity to identify common machines in their homes and school.; Assemble simple machines for learners to explore their uses in the home.; Help learners to demonstrate the use of the provided machines for undertaking various tasks.eg opening bottles, picking up granules, etc.; Elaborate on the importance of such machines on daily living.; Summarise learners’ responses by explaining that machines enable work to be done easier and faster.; Engage learners to draw any of the devices of their choice. Precaution: Knives and other sharp objects should not be used in this lesson.', 230),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B1.5.1.1', 'Recognise the importance of personal hygiene', 'B1.5.1.1.1', 'Explain the need for bathing and know how it is done', 'Enquire from learners routine activities they engage in before coming to school. (Activities may include sweeping, bathing, brushing of teeth, washing of face etc.; Lead learners to discuss the reasons for undertaking those activities (such as bathing); Assist them to talk about the number of times they bath a day and how their parents bath them; Display a video/pictures showing the items used in bathing; Present real items (e.g. soap, sponge, water, and towel) to learners to talk about them in groups; Guide learners to talk about what will happen if they do not take their bath regularly; In groups, learners present their ideas about what will happen if they do not bath; Learners sing familiar songs and recite rhymes as they demonstrate the process of bathing using a doll; Learners draw some items used for bathing and display them for discussion', 240),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B1.5.1.1', 'Recognise the importance of personal hygiene', 'B1.5.1.1.2', 'Know the need for and how to clean the teeth', 'Begin with a familiar song on cleaning the teeth.; Ask learners to mention the items used in cleaning the teeth, e.g. toothbrush and toothpaste, chewing stick etc.; Let learners watch an audio visual or pictures that show the right way to clean the teeth.; Demonstrate the right method of brushing the teeth (moving the toothbrush in an upward and downward motion) in front of the class and ask learners to do same.; Let learners individually draw and colour some items used in brushing the teeth and display their drawings for discussion.; Learners talk about what will happen if they do not brush their teeth regularly.', 250),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B1.5.1.1', 'Recognise the importance of personal hygiene', 'B1.5.1.1.3', 'Demonstrate understanding of the need for and how to wash the hands', 'Lead learners through questions to come out with the importance of washing the hands; Elaborate on their responses to introduce the topic “Hand-Washing”; Learners discuss when to wash their hands. (The hands must be washed after visiting the toilet, before eating and after eating, after practical activity, after returning to the home from school or the playground); Ask learners to name items used in hand-washing, (soap and running clean water); Bring to the classroom, items used for hand-washing and demonstrate the washing of hands to learners, emphasizing washing under running/flowing water; Engage learners in groups to demonstrate washing of hands; Learners brainstorm on the possible health effects associated with failure to wash the hands properly; Ask learners to draw illustrations of them washing their hands with water', 260),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B1.5.1.2', 'Appreciate the natural and human features of the local environment and the need for keeping the environment clean', 'B1.5.1.2.1', 'know that clean air and water are essential to human health', 'Go on a nature walk to observe the things in the environment; Learners talk about what they observed during the nature walk; Show pictures of the natural and human features of the environment; Engage learners to discuss what will happen to them if the environment is very dusty and unclean; Brainstorm with learners on what will happen if they do not weed or keep their school, home and community clean.; In groups learners present their ideas by explaining further why it is important to keep the environment clean.; Learners compose songs on how to keep the environment clean and draw pictures to depict clean environments.', 270),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B1.5.2.1', 'Know common diseases of humans, causes, symptoms, effects and prevention', 'B1.5.2.1.1', 'Identify some common diseases that affect the skin and their causes', 'Engage learners to watch pictures and videos or tell a story on common skin diseases; Learners into groups name some common skin diseases that affect people in their communities, e.g. heat rashes, measles, eczema, ringworm, chicken pox etc.; In groups learners share their ideas with the whole class; Reinforce learners’ ideas by writing all common skin diseases on the board; Brainstorm with learners on the causes of common skin diseases; Learners talk about the ways they can prevent skin diseases and role play some of the prevention scenarios', 280),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B1.5.3.1', 'Recognise the impact of science and technology on society', 'B1.5.3.1.1', 'Identify technologies in the immediate environment and describe the impact of the technology on society', 'Engage learners to watch videos or pictures showing technologies and their impact on the society; Bring electronic devices such as toys, laptops, smart phones, watches, radio and DVD players to class; Learners in groups discuss other technological equipment they see in their immediate environment and their accompanying functions, e.g. cars, drones, thermometers.; Learners present their ideas in groups for discussion; Ask learners to talk about what will happen if such technologies were absent in the society; Guide learners to reshape their ideas and present key concepts on common technologies in the environment on the writing board; Learners mention some technological devices and how these have impacted their lives; In groups learners work to design and make simple technological devices of their choice using materials such as blu tack, clay, cardboard and paper.', 290),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B1.5.3.2', 'Exhibit knowledge of food processing and preservation', 'B1.5.3.2.1', 'Identify foods that can be processed and preserved at home', 'Ask learners to mention foods they ate in the morning and what was used to prepare the food.; Provide samples of preserved foods such as roasted plantain, dried fish, smoked fish.; In groups, let learners name vegetables, fruits and other types of food that can be preserved at home, e.g. okro, pepper, tomato, onions, ginger, cassava, yam, plantain.; Learners talk about how food is prepared in their homes.; Ask learners to tell how their parents preserve food at home.; The food processing and preservation methods must include common ones such as smoking, drying, frying, roasting, baking and refrigeration.', 300),
('Basic 1', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B1.5.4.1', 'Understand that climate change is an important environmental issue facing the world today', 'B1.5.4.1.1', 'Describe the conditions of the weather', 'Take learners out to observe the weather and talk about whether they feel hot or cold.; Guide learners to talk about other weather conditions, e.g. rainy, windy, sunny and cloudy.; Show pictures or videos of different weather conditions and activities people do under different weather conditions.; Learners talk about what they observe during different weather conditions: rainy, windy, sunny and cloudy.; Let learners sing songs on the weather, e.g. rain, rain go away.; Act a play on the lesson taught.', 310);
